GAMES.push(...NEW_GAMES);
const EASY_WORDS=/^[A-Z]{2,6}$/;
const easyWord=w=>EASY_WORDS.test(w)&&!/(CH|CZ|SZ|RZ|DZ|CI|SI|NI|ZI|DZI)/.test(w);
const EASY_SYL=['MA','MO','MU','LA','LO','LU','TA','TO','TU','PA','PO','PU','BA','BO','BU','DA','DO','DU','SA','SO','SU','KA','KO','KU','RA','RO','RU','FA','FO','FU','NA','NO','NU','WA','WO'];
const TRAIN=[['LA','LA','🪆'],['MA','MA','👩'],['TA','TA','👨'],['LA','TO','☀️'],['LO','DY','🍦'],['SO','WA','🦉'],['KO','ZA','🐐'],['WO','DA','💧'],['KU','RA','🐔'],['RA','NO','🌅'],['BU','DA','🐶'],['MA','PA','🗺️'],['FA','LA','🌊'],['RO','SA','💧'],['LU','PA','🔎'],['RA','MA','🖼️'],['KO','RA','🌳'],['PO','LE','🌾'],['NO','GA','🦵'],['MA','TA','🧘'],['BA','ZA','🏕️'],['SA','LA','🏫'],['TA','MA','🌊'],['WO','REK','🛍️'],['MO','TYL','🦋'],['BA','LON','🎈'],['PO','MOC','🤝'],['PA','SEK','👖']];
const FOOD=[['🍎','JABŁKO'],['🍐','GRUSZKA'],['🍌','BANAN'],['🍓','TRUSKAWKA'],['🧀','SER'],['🍞','CHLEB'],['🥛','MLEKO'],['🍇','WINOGRONA'],['🍉','ARBUZ']];
const MOVES=[['🤸','Pajacyki','Zrób kilka pajacyków albo unieś ręce.'],['🙆','Ręce do góry','Unieś ręce do góry, a potem opuść.'],['👏','Klaszczemy','Klaszcz w rytm muzyki.'],['🕺','Taniec','Zatańcz tak, jak lubisz.'],['🙇','Skłony','Zrób kilka spokojnych skłonów albo porusz ramionami.'],['🐧','Pingwinek','Zrób kilka małych kroków w miejscu.']];
const PADS=['🥁','🔔','🎵'];const NOTES=[196,392,523.25];
let musicCtx=null, musicJobs=[], activeNotes=new Set();
function soundNote(freq,when=0,duration=.20,kind='triangle'){if(!store.sound)return;try{const C=window.AudioContext||window.webkitAudioContext;if(!C)return;musicCtx=musicCtx||new C();void musicCtx.resume().catch(()=>{});const o=musicCtx.createOscillator(),g=musicCtx.createGain(),t=musicCtx.currentTime+when;o.type=kind;o.frequency.value=freq;g.gain.setValueAtTime(.001,t);g.gain.exponentialRampToValueAtTime(.13,t+.025);g.gain.exponentialRampToValueAtTime(.001,t+duration);o.connect(g);g.connect(musicCtx.destination);activeNotes.add(o);o.onended=()=>{activeNotes.delete(o);o.disconnect();g.disconnect()};o.start(t);o.stop(t+duration+.02)}catch{}}
function stopMusic(){for(const t of musicJobs)clearTimeout(t);musicJobs=[];for(const o of activeNotes){try{o.stop()}catch{}}activeNotes.clear()}
function musicLater(fn,ms){const t=token;musicJobs.push(setTimeout(()=>{if(t===token&&screen==='game')fn()},ms))}
function newTask(x){if(ADVENTURES.includes(x.game)){adventureTask(x);return}switch(x.game){
case'room':roomTask(x);break;
case'forest':{const count=pick([4,5,6,7]);x.cells=shuffle([...Array(count).fill('🍄'),...Array.from({length:20-count},()=>pick(['🌿','🍂','🌲','🪵','🪨','🌱','🍁']))]);x.found=[];x.count=count;x.audio='Odszukaj wszystkie grzyby w lesie.';break}
case'treasure':{x.pos=pick([0,1,4,5]);x.prize=pick(PICTURE_WORDS.filter(([w])=>easyWord(w)));x.path=[];let p=x.pos;for(let i=0;i<4;i++){const dirs=[['→',1,p%4<3],['←',-1,p%4>0],['↓',4,p<12],['↑',-4,p>=4]].filter(d=>d[2]&&p+d[1]!==x.path.at(-1)?.from);const d=pick(dirs);x.path.push({from:p,to:p+d[1],arrow:d[0]});p+=d[1]}x.step=0;x.audio='Podążaj za strzałkami. Odkryj skarb!';break}
case'rhythm':x.seq=Array.from({length:store.level==='challenge'?4:3},()=>pick([0,1,2]));x.input=[];x.playing=false;x.flash=-1;x.heard=false;x.audio='Posłuchaj melodii i zagraj tak samo.';break;
case'dance':x.moves=shuffle(MOVES).slice(0,3);x.move=0;x.playing=false;x.beat=0;x.audio='Zrób sobie miejsce. Zatańcz razem ze mną!';break;
case'train':{const t=pick(TRAIN.filter(t=>store.level==='challenge'||t[1].length===2));x.parts=t.slice(0,2);x.word=x.parts.join('');x.pic=t[2];x.tiles=shuffle([...new Set([...x.parts,...shuffle(EASY_SYL.filter(s=>!x.parts.includes(s))).slice(0,2)])]);x.input=[];x.audio=x.word.toLowerCase();break}
case'shop':{x.items=shuffle(FOOD).slice(0,3).map(([pic,name])=>({pic,name,price:pick([2,3,4,5,6,7])}));x.order=shuffle([0,1,2]).slice(0,2);x.basket=[];x.total=x.order.reduce((a,i)=>a+x.items[i].price,0);x.paid=0;x.coins=[];x.audio='Włóż do koszyka produkty z listy, a potem zapłać.';break}
}}
function puppet(extra=''){return `<div class="puppet ${extra}" aria-hidden="true"><svg viewBox="0 0 180 190"><ellipse cx="65" cy="45" rx="22" ry="40" fill="#fff1df" stroke="#ba795c" stroke-width="3" transform="rotate(-13 65 45)"/><ellipse cx="115" cy="45" rx="22" ry="40" fill="#fff1df" stroke="#ba795c" stroke-width="3" transform="rotate(13 115 45)"/><ellipse cx="65" cy="44" rx="10" ry="24" fill="#f5aabe"/><ellipse cx="115" cy="44" rx="10" ry="24" fill="#f5aabe"/><ellipse cx="90" cy="148" rx="39" ry="36" fill="#91cfc2"/><path d="M57 146 Q31 131 25 147 Q32 163 59 159 M123 146 Q149 131 155 147 Q148 163 121 159" fill="#fff1df" stroke="#ba795c" stroke-width="3"/><ellipse cx="90" cy="97" rx="60" ry="49" fill="#fff1df" stroke="#ba795c" stroke-width="3"/><circle cx="69" cy="91" r="5" fill="#463735"/><circle cx="111" cy="91" r="5" fill="#463735"/><circle cx="49" cy="106" r="9" fill="#f6b0bd"/><circle cx="131" cy="106" r="9" fill="#f6b0bd"/><path d="M84 103 Q90 98 96 103 L90 110Z" fill="#cd7790"/><path d="M78 115 Q90 130 102 115" fill="none" stroke="#7d4d49" stroke-width="3" stroke-linecap="round"/><path d="M64 144 L90 156 L116 144 L116 168 L90 156 L64 168Z" fill="#eb865a"/></svg></div>`}
function newRender(x){if(ADVENTURES.includes(x.game))return adventureRender(x);if(x.game==='room')return roomRender(x);let q='',body='',hint='';switch(x.game){
case'forest':q='Znajdź grzyby i włóż je do koszyka';body=`<div class="basket">🧺 ${x.found.length} / ${x.count} ${'🍄'.repeat(x.found.length)}</div><div class="forest-board">${x.cells.map((e,i)=>`<button class="forest-cell ${x.found.includes(i)?'picked':''}" data-new="forest" data-i="${i}" ${x.found.includes(i)||x.solved?'disabled':''} aria-label="${x.found.includes(i)?'Zebrany grzyb':e==='🍄'?'Grzyb':'Leśny zakamarek'}"><span style="--angle:${(i*17%31)-15}deg">${x.found.includes(i)?'✨':e}</span></button>`).join('')}</div><p class="sub">To zabawa obrazkami. Prawdziwe grzyby oglądaj tylko z dorosłym.</p>`;hint='Szukaj obrazka 🍄 między liśćmi i drzewami.';break;
case'treasure':q=x.solved?'Skarb jest Twój!':'Którędy prowadzi mapa?';body=`<div class="route">${x.path.map((d,i)=>`<span class="${i<x.step?'past':i===x.step?'current':''}">${i<x.step?'✓':d.arrow}</span>`).join('')}</div><div class="treasure-board">${Array.from({length:16},(_,i)=>`<button data-new="treasure" data-i="${i}" class="map-cell ${i===x.pos?'here':''} ${x.wrong===i?'retry':''}" ${x.solved?'disabled':''} aria-label="Pole ${Math.floor(i/4)+1}, ${i%4+1}">${i===x.pos?(x.solved?'🏆':'🦊'):['🌿','🌲','🍂','🌼'][i%4]}</button>`).join('')}</div>${x.solved?`<div class="basket">${x.prize[1]} <strong>${esc(x.prize[0])}</strong> <button class="small" data-act="listen">🔊</button></div>`:'<p class="sub">Dotknij pola obok liska zgodnie ze strzałką.</p>'}`;hint='Zacznij od podświetlonej strzałki. Przesuń się o jedno pole.';break;
case'rhythm':q='Zagraj melodię Luli';body=`<div class="mascot-row">${puppet(x.playing?'bop':'')}<div><button class="primary" data-new="rhythmplay" ${x.playing||x.solved?'disabled':''}>▶ Posłuchaj</button><p class="sub">${x.playing?'Słuchaj i patrz!':x.heard?'Teraz Twoja kolej.':'Najpierw posłuchaj.'}</p></div></div><div class="rhythm-progress">${x.seq.map((n,i)=>`<span>${i<x.input.length?'⭐':x.hint?PADS[n]:'○'}</span>`).join('')}</div><div class="pad-row">${PADS.map((p,i)=>`<button class="pad pad${i} ${x.flash===i?'lit':''}" data-new="pad" data-i="${i}" ${x.playing||!x.heard||x.solved?'disabled':''}>${p}</button>`).join('')}</div>`;hint='Patrz na podpowiedź i odtwarzaj po kolei.';break;
case'dance':{const m=x.moves[Math.min(x.move,x.moves.length-1)];q='Przerwa na ruch!';body=`<div class="dance-stage ${x.playing?'dancing':''}">${puppet(x.playing?'bop':'')}<div class="dance-move"><div class="move-icon">${m[0]}</div><h2>${m[1]}</h2><p>${m[2]}</p><div class="beats">${Array.from({length:4},(_,i)=>`<span class="${x.playing&&x.beat%4===i?'beat-on':''}">♫</span>`).join('')}</div></div></div><div class="actions"><button class="primary" data-new="danceplay" ${x.solved?'disabled':''}>${x.playing?'⏸ Zatrzymaj muzykę':'▶ Włącz muzykę'}</button><button class="small" data-new="dancenext" ${x.solved?'disabled':''}>${x.move===2?'✨ Gotowe!':'Następny ruch ➜'}</button></div><p class="sub">Zostaw miejsce wokół siebie. Możesz też tańczyć na siedząco. Sama decydujesz, kiedy kończysz.</p>`;hint='Nie musisz robić wszystkiego. Wybierz swój ulubiony ruch.';break}
case'train':q='Połącz sylaby w słowo';body=`<div class="pic">${x.pic}</div>${listen('Posłuchaj słowa')}<div class="train-slots">🚂 ${x.parts.map((p,i)=>`<span>${x.input[i]||'···'}</span>`).join('')}</div><div class="train-tiles">${x.tiles.map(s=>`<button class="letter" data-new="train" data-value="${s}" ${x.solved?'disabled':''}>${s}</button>`).join('')}</div>${x.solved?`<div class="big">${x.word}</div>`:''}`;hint=`Przeczytaj razem z dorosłym: <strong>${x.parts.join(' – ')}</strong>`;break;
case'shop':q=x.basket.length<2?'Zrób zakupy z listy':'Zapłać za zakupy';body=`<div class="shop-list">Lista: ${x.order.map(i=>`<span>${x.items[i].pic}${x.basket.includes(i)?' ✓':''}</span>`).join('')}</div><div class="shop-shelf">${x.items.map((it,i)=>`<button data-new="shopitem" data-i="${i}" ${x.basket.includes(i)||x.basket.length===2||x.solved?'disabled':''}><span>${it.pic}</span><strong>${it.price} zł</strong></button>`).join('')}</div><div class="basket">🛒 ${x.basket.map(i=>x.items[i].pic).join(' ')}${x.basket.length===2?` · Razem ${x.total} zł`:''}</div>${x.basket.length===2?`<p class="question">Zapłacono: ${x.paid} zł / ${x.total} zł</p><div class="coins">${[1,2,5].map(n=>`<button data-new="coin" data-i="${n}" ${x.solved?'disabled':''}>${n} zł</button>`).join('')}</div><button class="small" data-new="undo" ${!x.coins.length||x.solved?'disabled':''}>↶ Cofnij monetę</button>`:''}`;hint=x.basket.length<2?'Wybierz produkty z listy.':`Dobierz monety, aby uzyskać dokładnie ${x.total} zł.`;break;
}return {q,body,hint}}
function playRhythm(){const x=task;if(x.playing||x.solved)return;stopMusic();stopVoice();x.playing=true;x.input=[];x.wrong=null;x.flash=-1;render();x.seq.forEach((n,i)=>musicLater(()=>{x.flash=n;soundNote(NOTES[n]);render();musicLater(()=>{x.flash=-1;render()},300)},i*640+100));musicLater(()=>{x.playing=false;x.heard=true;x.flash=-1;render()},x.seq.length*640+150)}
function danceMusic(){const x=task;if(x.solved)return;if(x.playing){stopMusic();x.playing=false;render();return}stopVoice();x.playing=true;x.beat=0;const melody=[261.63,329.63,392,329.63,293.66,349.23,440,349.23,261.63,329.63,392,523.25,392,329.63,293.66,261.63];function tick(){if(task!==x||!x.playing)return;if(x.beat>=32){x.playing=false;render();return}x.beat++;soundNote(melody[(x.beat-1)%melody.length],0,.32);if(x.beat%2===1)soundNote(130.81,0,.18,'sine');render();musicLater(tick,480)}tick()}
function newClick(d){const x=task;if(!x||x.solved)return;const i=Number(d.i);if(ADVENTURES.includes(x.game)){adventureClick(x,d,i);return}if(x.game==='room'){roomClick(x,d,i);return}switch(d.new){
case'forest':if(x.cells[i]==='🍄'&&!x.found.includes(i)){x.found.push(i);soundNote(523.25);if(x.found.length===x.count)mark()}break;
case'treasure':if(i===x.path[x.step].to){x.pos=i;x.step++;x.wrong=null;soundNote(392);if(x.step===x.path.length){x.audio=x.prize[0].toLowerCase();store.treasures=unique([...(store.treasures||[]),x.prize[0]]);mark();saySequence(['Brawo!',x.audio])}}else if(i!==x.pos)x.wrong=i;break;
case'rhythmplay':playRhythm();return;
case'pad':if(x.playing||!x.heard)return;soundNote(NOTES[i]);if(i===x.seq[x.input.length]){x.input.push(i);x.wrong=null;if(x.input.length===x.seq.length)mark()}else{x.wrong=i}break;
case'danceplay':danceMusic();return;
case'dancenext':stopMusic();x.playing=false;if(x.move===x.moves.length-1)mark();else{x.move++;x.beat=0;say(x.moves[x.move][2])}break;
case'train':if(d.value===x.parts[x.input.length]){x.input.push(d.value);x.wrong=null;if(x.input.length===x.parts.length){mark();saySequence([x.parts[0].toLowerCase(),x.parts[1].toLowerCase(),x.word.toLowerCase()])}else say(d.value.toLowerCase())}else{x.wrong=d.value}break;
case'shopitem':if(x.order.includes(i)&&!x.basket.includes(i)){x.basket.push(i);x.wrong=null;soundNote(440);if(x.basket.length===2)say('Teraz zapłać za zakupy.')}else x.wrong=i;break;
case'coin':if(x.basket.length!==2)return;x.coins.push(i);x.paid+=i;if(x.paid===x.total)mark();else if(x.paid>x.total){x.coins.pop();x.paid-=i;x.wrong=i}else{x.wrong=null;soundNote(523.25)}break;
case'undo':if(x.coins.length)x.paid-=x.coins.pop();x.wrong=null;break;
}render()}

// Mystery house: randomized hide-and-seek, free room navigation, optional word lock.
const ROOM_PROPS=[
 {name:'Salon',icon:'🛋️',wall:'#f7d9be',floor:'#bf8c69',props:[['fotel','🪑',15,62],['szafka','🗄️',20,29],['obraz','🖼️',44,20],['kanapa','🛋️',53,61],['roślina','🪴',85,48],['pudełko','📦',78,78]]},
 {name:'Pokój zabaw',icon:'🧸',wall:'#d9e7fc',floor:'#ad9bd0',props:[['łóżko','🛏️',23,65],['półka','📚',21,25],['zegarek','🕰️',51,20],['domek','🏠',52,62],['miś','🧸',82,34],['kosz','🧺',83,76]]},
 {name:'Kuchnia',icon:'🍎',wall:'#d9f0d5',floor:'#c29d6c',props:[['lodówka','🧊',15,42],['szafka','🗄️',43,24],['kubek','☕',77,24],['stół','🍽️',54,67],['kosz','🧺',15,80],['doniczka','🪴',84,73]]}
];
const ROOM_WORDS=[['KOT','🐈'],['LIS','🦊'],['DOM','🏠'],['SER','🧀'],['NOS','👃'],['OKO','👁️'],['RAK','🦞'],['BUT','👟'],['AUTO','🚗'],['RYBA','🐟'],['SOWA','🦉'],['KURA','🐔'],['KOZA','🐐'],['MELON','🍈'],['BALON','🎈'],['MAPA','🗺️'],['LUPA','🔎'],['TORT','🎂'],['BANAN','🍌'],['PANDA','🐼'],['MOTYL','🦋'],['ROWER','🚲'],['KUBEK','☕'],['PIES','🐕'],['BORSUK','🦡'],['KROWA','🐄']];
function roomTask(x){
 const targets=shuffle(ROOM_WORDS).slice(0,3);x.targets=targets;x.room=0;x.openBox=null;x.found=[];x.checked=[];x.roomHint=false;x.lock=null;x.input=[];x.audio='Poszukaj ukrytych skarbów w domku.';
 x.rooms=ROOM_PROPS.map((r,i)=>{const at=pick(range(0,5));const extras=shuffle(ROOM_WORDS.filter(w=>!targets.some(t=>t[0]===w[0]))).slice(0,5);return r.props.map((p,j)=>({prop:p,item:j===at?targets[i]:extras.pop(),target:j===at}))});
}
function roomScene(r){return `<svg class="room-art" viewBox="0 0 800 480" preserveAspectRatio="none" aria-hidden="true"><defs><pattern id="roomfloor" width="104" height="40" patternUnits="userSpaceOnUse"><path d="M0 0H104M0 40H104M${r.name==='Kuchnia'?52:24} 0V40" fill="none" stroke="#ffffff" stroke-opacity=".28" stroke-width="3"/></pattern></defs><rect width="800" height="480" fill="${r.wall}"/><path d="M0 302H800V480H0Z" fill="${r.floor}"/><path d="M0 302H800V480H0Z" fill="url(#roomfloor)"/><path d="M0 302H800" stroke="#ffffff" stroke-width="13"/><rect x="306" y="45" width="185" height="133" rx="12" fill="#fdf9e8" stroke="#997f72" stroke-width="7"/><rect x="320" y="59" width="157" height="105" rx="5" fill="#89d6ef"/><circle cx="449" cy="84" r="19" fill="#ffe48a"/><path d="M320 146Q361 88 403 146T477 134V164H320" fill="#9ac78e"/><path d="M398 61V164M320 110H477" stroke="#fff9e8" stroke-width="7"/><rect x="265" y="326" width="310" height="100" rx="50" fill="${r.wall}" stroke="#fffaf1" stroke-width="8"/><rect x="282" y="341" width="276" height="70" rx="35" fill="none" stroke="#fffaf1" stroke-width="3" stroke-dasharray="8 6"/><path d="M0 5H800" stroke="#fffaf1" stroke-width="10"/></svg>`}
function roomRender(x){
 const r=ROOM_PROPS[x.room];const f=x.openBox===null?null:x.rooms[x.room][x.openBox];const key=x.openBox===null?'':x.room+':'+x.openBox;
 const found=x.found.length;
 let panel='';
 if(x.solved){panel=`<div class="room-reveal room-celebrate"><span class="room-prize">🏆</span><h3>Wszystkie skarby odnalezione!</h3><p>Możesz ruszać na kolejną wyprawę.</p></div>`}
 else if(x.lock){const [word,pic]=x.lock;panel=`<div class="room-reveal"><div class="room-prize">🧰 ${pic}</div><h3>Tajemnicza skrzynia</h3><p>Ułóż taki sam napis albo poproś Lulę o pomoc.</p><div class="room-model">${word}</div><button class="small" data-new="roomListen">🔊 Posłuchaj</button><div class="room-slots">${[...word].map((l,i)=>`<span>${x.input[i]||'·'}</span>`).join('')}</div><div class="room-letters">${x.tiles.map((l,i)=>`<button class="letter" data-new="roomLetter" data-i="${i}" ${x.used.includes(i)?'disabled':''}>${l}</button>`).join('')}</div><button class="small" data-new="roomHelp">🐰 Otwórz z Lulą</button></div>`}
 else if(f){panel=`<div class="room-reveal" role="status"><div class="room-prize">${f.item[1]}</div><h3>${f.item[0]}</h3><p>${x.found.includes(key)?'Ten skarb już jest w kolekcji.':f.target?'To właśnie skarb z listy!':'Ciekawy przedmiot! Szukamy jeszcze innych skarbów.'}</p><div class="actions"><button class="small" data-new="roomListen">🔊 Posłuchaj</button>${f.target&&!x.found.includes(key)?'<button class="primary" data-new="roomTake">🎒 Zabierz skarb</button>':''}<button class="small" data-new="roomClose">↩ Szukaj dalej</button></div></div>`}
 else if(found===3){panel='<div class="room-reveal"><span class="room-prize">🧰</span><h3>Wielka niespodzianka!</h3><button class="primary" data-new="roomChest">Otwórz skrzynię</button></div>'}
 else panel='<div class="room-tip">🕵️ Dotykaj mebli i sprawdzaj, co się w nich ukryło.</div>';
 return {q:'Tajemniczy domek',body:`<div class="room-quest"><strong>Znajdź skarby</strong><div>${x.targets.map(([w,p],i)=>`<button class="room-target ${x.found.some(k=>k.startsWith(i+':'))?'collected':''}" data-new="roomTarget" data-i="${i}" aria-label="Posłuchaj: ${w}">${p}<span>${x.found.some(k=>k.startsWith(i+':'))?'✓':w}</span></button>`).join('')}</div><span>${found}/3 🎒</span></div><nav class="room-nav" aria-label="Pokoje">${ROOM_PROPS.map((p,i)=>`<button class="small ${x.room===i?'active':''}" data-new="roomGo" data-i="${i}" ${x.lock||x.solved?'disabled':''}>${p.icon} <span>${p.name}</span></button>`).join('')}</nav><div class="room-scene">${roomScene(r)}${x.rooms[x.room].map(({prop},i)=>{const k=x.room+':'+i;const seen=x.checked.includes(k);return `<button class="room-prop ${seen?'seen':''} ${x.openBox===i?'opened':''} ${x.hint&&x.rooms[x.room][i].target&&!x.found.includes(k)?'glow':''}" style="--x:${prop[2]}%;--y:${prop[3]}%" data-new="roomOpen" data-i="${i}" aria-label="Sprawdź: ${prop[0]}" ${x.lock||x.solved?'disabled':''}><span>${prop[1]}</span><i>${x.found.includes(k)?'✓':seen?'·':'?'}</i></button>`}).join('')}</div>${panel}`,hint:'W każdym pokoju ukrył się jeden skarb. Złote światło pokazuje miejsce, w którym warto zajrzeć.'};
}
function roomClick(x,d,i){switch(d.new){
 case'roomGo':if(!x.lock){x.room=i;x.openBox=null;x.hint=false;stopVoice()}break;
 case'roomOpen':if(!x.lock){x.openBox=i;const k=x.room+':'+i;if(!x.checked.includes(k))x.checked.push(k);soundNote(392);say(x.rooms[x.room][i].item[0].toLowerCase())}break;
 case'roomClose':x.openBox=null;break;
 case'roomTarget':say(x.targets[i][0].toLowerCase(),true);return;
 case'roomListen':if(x.lock)say(x.lock[0].toLowerCase(),true);else if(x.openBox!==null)say(x.rooms[x.room][x.openBox].item[0].toLowerCase(),true);return;
 case'roomTake':{if(x.openBox===null)return;const k=x.room+':'+x.openBox;const f=x.rooms[x.room][x.openBox];if(!f?.target||x.found.includes(k))return;x.found.push(k);store.treasures=unique([...(store.treasures||[]),f.item[0]]);save();x.openBox=null;x.hint=false;soundNote(523.25,0,.3);say(pick(PRAISE));break}
 case'roomChest':if(x.found.length===3){x.lock=pick(x.targets.filter(t=>t[0].length<=5).length?x.targets.filter(t=>t[0].length<=5):x.targets);x.tiles=shuffle([...x.lock[0]]);x.used=[];x.input=[];say(x.lock[0].toLowerCase())}break;
 case'roomLetter':if(x.lock&&!x.used.includes(i)&&x.tiles[i]===x.lock[0][x.input.length]){x.used.push(i);x.input.push(x.tiles[i]);soundNote(440);if(x.input.join('')===x.lock[0]){mark();saySequence(['Brawo!',x.lock[0].toLowerCase()])}}else if(x.lock)soundNote(262,0,.13);break;
 case'roomHelp':if(x.lock){x.input=[...x.lock[0]];task.hint=true;mark();saySequence(['Brawo!',x.lock[0].toLowerCase()])}break;
 }render()}

// v1.3: three playable exploration games. All paths allow retry or assistance.
const ADVENTURES=['bridge','attic','cave'];
const BRIDGE_COLORS=['#92d9f7','#bbafff','#a2e6c7'];
const ATTIC_PROPS=[['kufer','🧰',15,73],['globus','🌍',21,35],['obraz','🖼️',43,26],['regał','📚',75,39],['walizka','🧳',58,77],['stary zegar','🕰️',86,77]];
const CAVE_ITEMS=[['GEM','💎'],['KOT','🐈'],['MAPA','🗺️'],['LUPA','🔎'],['BALON','🎈'],['SER','🧀'],['RAK','🦞'],['TORT','🎂']].filter(a=>a[0]!=='GEM');
function adventureTask(x){
 if(x.game==='bridge'){x.route=Array.from({length:store.level==='challenge'?6:4},()=>pick([0,1]));x.step=0;x.preview=true;x.reveal=false;x.audio='Zapamiętaj drogę. Jak uda ci się przejść, odkryjesz skarb!';x.prize=pick(ROOM_WORDS.filter(w=>easyWord(w[0])))}
 if(x.game==='attic'){x.keys=shuffle([0,1,2,4,5]).slice(0,3);x.found=[];x.open=-1;x.secret=false;x.order=shuffle(['⭐','🌙','☀️']);x.input=[];x.prize=pick(ROOM_WORDS.filter(w=>easyWord(w[0])));x.audio='Poszukaj trzech kluczy. Za regałem ukrywa się tajemnica.'}
 if(x.game==='cave'){x.items=shuffle(CAVE_ITEMS).slice(0,3).map((a,i)=>({word:a[0],pic:a[1],...{x:[18,51,82][i]+pick([-5,0,5]),y:pick([29,46,68,79])}}));x.found=[];x.light={x:50,y:50};x.audio='Przesuwaj palcem latarkę i szukaj trzech skarbów.'}
}
function collectWord(w){store.treasures=unique([...(store.treasures||[]),w]);save()}
function bridgeScene(x){
 let rows='';for(let i=x.route.length-1;i>=0;i--){const near=1-i*.055;const options=[0,1].map(j=>{let ok=(x.preview||x.reveal||x.hint)&&x.route[i]===j,done=i<x.step&&x.route[i]===j,bad=x.wrong===j&&i===x.step;return `<button class="glass-tile ${ok?'lit':''} ${done?'crossed':''} ${bad?'wobble':''}" data-new="bridgeStep" data-i="${j}" style="--glass:${BRIDGE_COLORS[(i+j)%3]}" ${i!==x.step||x.preview||x.solved?'disabled':''} aria-label="${j===0?'Lewa':'Prawa'} płytka, krok ${i+1}${ok?', bezpieczna':''}">${done?(i===x.step-1&&!x.solved?'🦊':'⭐'):ok?'✦':bad?'💫':'◈'}</button>`}).join('');rows+=`<div class="glass-row" style="--scale:${near}">${options}</div>`}
 // Reverse the stack visually: first step is nearest the player at bottom.
 return `<div class="bridge-landscape"><svg viewBox="0 0 900 600" preserveAspectRatio="xMidYMid slice" aria-hidden="true"><defs><linearGradient id="sky13" x2="0" y2="1"><stop stop-color="#796dcc"/><stop offset="1" stop-color="#a5e5ed"/></linearGradient></defs><path fill="url(#sky13)" d="M0 0H900V600H0Z"/><circle cx="736" cy="97" r="46" fill="#fff3ae"/><path fill="#b7c7ed" d="M0 480L185 170 350 390 560 130 900 480V600H0Z"/><path fill="#dbf5fa" d="M119 290L185 170 252 270 190 251 167 275ZM481 255L560 130 661 300 563 241 531 268Z"/><g fill="#fff" opacity=".7"><ellipse cx="135" cy="130" rx="101" ry="28"/><ellipse cx="100" cy="110" rx="51" ry="31"/><ellipse cx="780" cy="349" rx="112" ry="31"/><ellipse cx="814" cy="327" rx="48" ry="35"/></g><path d="M0 548Q180 482 295 555T610 558T900 540V600H0Z" fill="#81b88a"/></svg><div class="bridge-end">${x.solved?'🏆':'🎁'} <span>Wyspa skarbów</span></div><div class="glass-stack">${rows}</div><div class="bridge-player">${x.solved?'✨':x.step===0?'🦊':'👣'} <span>${x.step} / ${x.route.length}</span></div></div>`
}
function atticBackground(){return `<svg viewBox="0 0 800 480" preserveAspectRatio="none" aria-hidden="true"><path fill="#f2d5ad" d="M0 0H800V480H0Z"/><path fill="#c89668" d="M0 320H800V480H0Z"/><path fill="#9c6648" d="M0 0L400 0 0 240ZM800 0L400 0 800 240Z"/><path d="M0 244L400 15 800 244M400 10V320M0 320H800" fill="none" stroke="#895739" stroke-width="12"/><g stroke="#e9b587" stroke-width="3"><path d="M0 358H800M0 400H800M0 445H800M100 321L50 480M300 321L280 480M500 321L520 480M700 321L750 480"/></g><circle cx="400" cy="122" r="61" fill="#f9f5df" stroke="#a7734b" stroke-width="7"/><circle cx="400" cy="122" r="49" fill="#a1d9ef"/><path d="M400 73V171M351 122H449" stroke="#fff7e3" stroke-width="6"/><path d="M335 356Q400 327 465 356L510 437H290Z" fill="#c46355" opacity=".75"/><g fill="#fff3d5" opacity=".8"><circle cx="200" cy="175" r="3"/><circle cx="305" cy="217" r="4"/><circle cx="680" cy="208" r="4"/></g></svg>`}
function caveBackground(){return `<svg viewBox="0 0 800 480" preserveAspectRatio="none" aria-hidden="true"><defs><linearGradient id="rock13" x2=".8" y2="1"><stop stop-color="#76659e"/><stop offset="1" stop-color="#3e3c70"/></linearGradient></defs><rect width="800" height="480" fill="#625882"/><path d="M0 0H800V480H0Z M90 440L80 200Q110 20 400 38Q690 30 720 200L710 440Z" fill="url(#rock13)" fill-rule="evenodd"/><path d="M0 0L120 0 87 120 169 13 219 0 262 112 309 0 439 0 475 88 520 0 648 0 687 131 740 0 800 0V0Z" fill="#423757"/><path d="M0 380L80 336 146 400 220 358 320 423 485 376 551 412 676 350 800 390V480H0Z" fill="#50466e"/><g fill="#9c8bdd" opacity=".72"><path d="M44 367L62 303 85 365 69 405Z M726 246L750 181 771 246 750 286Z M528 410L547 363 568 411 550 443Z"/></g><g fill="#d7b6ed" opacity=".4"><circle cx="290" cy="155" r="6"/><circle cx="643" cy="98" r="5"/><circle cx="155" cy="260" r="5"/></g></svg>`}
function adventureRender(x){
 if(x.game==='bridge')return {q:x.solved?'Dotarłaś na wyspę!':x.preview?'Popatrz na świecące płytki': 'Przeskocz po zapamiętanej drodze',body:bridgeScene(x)+(x.solved?`<div class="discovery-prize">${x.prize[1]} <strong>${esc(x.prize[0])}</strong> <button class="small" data-act="listen">🔊</button></div>`:`<div class="actions"><button class="primary" data-new="bridgeStart">${x.preview?'▶ Ruszamy!':'👀 Pokaż drogę'}</button><button class="small" data-new="bridgeHelp">✨ Przejdź razem z Lulą</button></div>`),hint:'Bezpieczna płytka świeci. Możesz oglądać drogę dowolnie długo. Nie tracisz zrobionych kroków.'};
 if(x.game==='attic'){const opened=x.open>=0,prop=ATTIC_PROPS[x.open];let reveal='';if(x.solved)reveal=`<div class="discovery-prize">🎁 ${x.prize[1]} <strong>${esc(x.prize[0])}</strong> <button class="small" data-act="listen">🔊</button></div>`;else if(x.secret)reveal=`<div class="secret-panel"><div class="secret-door">🚪✨</div><h3>Otwórz magiczne drzwi</h3><div class="secret-code">${x.order.map((s,i)=>`<span>${i<x.input.length?'✓':s}</span>`).join('')}</div><div class="actions">${['☀️','🌙','⭐'].map((s,i)=>`<button class="answer secret-symbol" data-new="atticSymbol" data-i="${i}">${s}</button>`).join('')}</div><button class="small" data-new="atticHelp">🐰 Lula otworzy drzwi</button></div>`;else if(opened)reveal=`<div class="discovery-prize">${x.keys.includes(x.open)?'🗝️':'✨'} <strong>${x.keys.includes(x.open)?'Klucz znaleziony!':'Tu nie ma klucza. Szukaj dalej!'}</strong></div>`;
 return {q:x.secret?'Sekret za regałem!':'Gdzie schowały się klucze?',body:`<div class="basket">${'🗝️'.repeat(x.found.length)} ${x.found.length}/3</div><div class="attic-scene">${atticBackground()}${ATTIC_PROPS.map((p,i)=>`<button class="attic-prop ${x.found.includes(i)?'found':''} ${x.hint&&x.keys.includes(i)&&!x.found.includes(i)?'glow':''} ${i===3&&x.found.length===3?'glow':''}" style="--x:${p[2]}%;--y:${p[3]}%" data-new="atticOpen" data-i="${i}" ${x.secret||x.solved?'disabled':''} aria-label="Sprawdź ${p[0]}">${p[1]}${x.found.includes(i)?'<i>✓</i>':''}</button>`).join('')}</div>${!x.secret&&x.found.length===3?'<div class="actions"><button class="primary" data-new="atticDoor">📚 Zajrzyj za regał!</button></div>':''}${reveal}`,hint:'Dotykaj przedmiotów. Gdy znajdziesz trzy klucze, zajrzyj za regał.'};}
 if(x.game==='cave')return {q:x.solved?'Jaskinia odkryta!':'Zapal latarkę i szukaj skarbów',body:`<div class="basket">🔦 ${x.found.length}/3 · ${x.found.map(i=>x.items[i].pic).join(' ')}</div><div class="cave-scene ${x.hint||x.solved?'cave-bright':''}" id="caveScene" style="--lx:${x.light.x}%;--ly:${x.light.y}%" aria-label="Jaskinia. Przeciągnij palcem i dotknij skarbu.">${caveBackground()}${x.items.map((v,i)=>`<button data-new="caveTake" data-i="${i}" class="cave-item ${x.found.includes(i)?'collected':''}" style="--x:${v.x}%;--y:${v.y}%" ${x.found.includes(i)||x.solved?'disabled':''} aria-label="${x.found.includes(i)?'Zebrany skarb':'Skarb'}">${x.found.includes(i)?'✨':v.pic}</button>`).join('')}<div class="cave-dark"></div><div class="cave-beam"></div></div><p class="sub">Przesuwaj palcem światło. Dotknij obrazka, gdy go zobaczysz.</p>${x.found.length?`<div class="discovery-prize">${x.items[x.found.at(-1)].pic} <strong>${x.items[x.found.at(-1)].word}</strong> <button class="small" data-act="listen">🔊</button></div>`:''}<button class="small" data-new="caveLight">💡 ${x.hint?'Przygaś światło':'Rozjaśnij jaskinię'}</button>`,hint:'Możesz włączyć dodatkowe światło. Nie musisz szukać po ciemku.'};
}
function adventureClick(x,d,i){
 if(x.game==='bridge'){
  if(d.new==='bridgeStart'){x.preview=!x.preview;x.wrong=null}
  if(d.new==='bridgeHelp'){x.preview=false;x.reveal=true;x.hint=true;x.wrong=null}
  if(d.new==='bridgeStep'&&!x.preview){if(i===x.route[x.step]){x.step++;x.wrong=null;soundNote(440+x.step*55,0,.23);if(x.step===x.route.length){collectWord(x.prize[0]);x.audio=x.prize[0].toLowerCase();mark();saySequence(['Brawo!',x.audio])}}else{x.wrong=i;x.reveal=true;soundNote(262,0,.15);say('Spróbuj jeszcze raz.')}}
 }else if(x.game==='attic'){
  if(d.new==='atticOpen'&&!x.secret){x.open=i;if(i===3&&x.found.length===3){x.secret=true;soundNote(523.25);say('Odkryłaś sekretne przejście!')}else if(x.keys.includes(i)&&!x.found.includes(i)){x.found.push(i);soundNote(523.25);say('Udało się!')}}
  if(d.new==='atticDoor'&&x.found.length===3){x.secret=true;say('Odkryłaś sekretne przejście!')}
  if(x.secret&&d.new==='atticSymbol'){const s=['☀️','🌙','⭐'][i];if(s===x.order[x.input.length]){x.input.push(s);soundNote(440+x.input.length*55);x.wrong=null}else{x.wrong=i;soundNote(262)}}
  if(x.secret&&d.new==='atticHelp'){x.input=[...x.order];x.hint=true}
  if(x.input.length===3){collectWord(x.prize[0]);x.audio=x.prize[0].toLowerCase();mark();saySequence(['Brawo!',x.audio])}
 }else if(x.game==='cave'){
  if(d.new==='caveLight')x.hint=!x.hint;
  if(d.new==='caveTake'&&!x.found.includes(i)){const a=x.items[i];x.light={x:a.x,y:a.y};x.found.push(i);collectWord(a.word);x.audio=a.word.toLowerCase();soundNote(523.25);if(x.found.length===3){mark();saySequence(['Brawo!',x.audio])}else say(x.audio)}
 }render();
}
function setupCave(){const el=$('#caveScene');if(!el||task.solved)return;const x=task;let active=null;const aim=e=>{const r=el.getBoundingClientRect();x.light={x:Math.max(0,Math.min(100,(e.clientX-r.left)*100/r.width)),y:Math.max(0,Math.min(100,(e.clientY-r.top)*100/r.height))};el.style.setProperty('--lx',x.light.x+'%');el.style.setProperty('--ly',x.light.y+'%')};el.addEventListener('pointerdown',e=>{active=e.pointerId;aim(e)});el.addEventListener('pointermove',e=>{if(e.pointerType==='mouse'||active===e.pointerId)aim(e)});el.addEventListener('pointerup',e=>{active=null;aim(e)});el.addEventListener('pointercancel',()=>{active=null});}

