const MISSION_TYPES=[['art','🎨','Rysuję'],['detect','🔍','Szukam'],['words','✏️','Literki'],['build','🧱','Buduję'],['move','💃','Ruszam się'],['math','🧮','Liczę']];
const DECOR=[['🧶','Kłębek','floor'],['🪴','Roślinka','shelf'],['🌈','Tęcza','wall'],['🧸','Miś','floor'],['🍄','Grzybek','shelf'],['⭐','Gwiazda','wall'],['🚂','Pociąg','floor'],['🏆','Puchar','shelf'],['🖼️','Obrazek','wall'],['🪁','Latawiec','wall'],['🎁','Pudełko','floor'],['💎','Kryształ','shelf']];
function worldData(){if(!store.world||typeof store.world!=='object')store.world={unlocked:3,placed:{floor:0,shelf:1,wall:2},missionsDone:[],recent:[],active:null};return store.world}
function gift(album=true){if(album)awardAlbum(screen==='mission'?'other':store.lastGame);const w=worldData();if(w.unlocked<DECOR.length){w.unlocked++;return DECOR[w.unlocked-1]}return null}
function otherScreen(name){invalidate();screen=name;session=null;task=null;updateAtSafePoint()}
function worldMap(){otherScreen('world');const w=worldData();const sites=[['forest','🍄','Las grzybów',18,24],['bridge','🌈','Szklany most',78,20],['cave','🔦','Jaskinia',79,75],['room','🗝️','Dom tajemnic',20,75],['rhythm','🥁','Scena',49,20],['shop','🛒','Sklepik',52,77]];app.innerHTML=top()+`<section class="world-head"><h1>🌍 Kraina odkrywców</h1><p>Dotknij miejsca, do którego chcesz się wybrać.</p></section><div class="world-map"><svg viewBox="0 0 800 480" preserveAspectRatio="none" aria-hidden="true"><path fill="#bde5a6" d="M0 0H800V480H0Z"/><path fill="none" stroke="#89d4ec" stroke-width="76" d="M-30 140Q240 50 390 220T830 370"/><path fill="none" stroke="#f7dfac" stroke-width="26" stroke-linecap="round" d="M144 115L392 96L624 96M144 115L400 240L632 360M160 360L400 240L416 370"/><g font-size="48">${Array.from({length:14},(_,i)=>`<text x="${25+(i*137)%730}" y="${45+(i*93)%420}">${i%3?'🌲':'🌼'}</text>`).join('')}</g></svg>${sites.map(([id,ico,n,x,y])=>`<button class="world-pin" data-game="${id}" style="left:${x}%;top:${y}%"><span>${ico}</span><strong>${n}</strong></button>`).join('')}<button class="world-pin world-central" data-world="den" style="left:50%;top:49%"><span>🏡</span><strong>Mój domek</strong></button></div><div class="world-actions"><button class="primary" data-world="missions">🌟 ${w.active!==null?'Wróć do misji':'Misje poza ekranem'}</button><button class="small" data-act="home">Wszystkie gry</button></div><section class="collection"><h2>Nowe krainy</h2><div>${ACTIVE_GAMES.map(g=>`<button class="small" data-game="${g.id}">${g.icon} ${g.name}</button>`).join('')}</div></section><p class="foot">Każda kraina jest otwarta. Wybieraj bez pośpiechu.</p>`}
function den(message=''){otherScreen('den');const w=worldData();app.innerHTML=top()+`<section class="world-head"><h1>🏡 Mój domek</h1><p>Smok Pikuś czeka na wspólną zabawę!</p></section><div class="den-scene"><div class="den-window">☀️<span>🌳</span></div><div class="den-wall">${DECOR[w.placed.wall]?.[0]||''}</div><div class="den-shelf">${DECOR[w.placed.shelf]?.[0]||''}</div><div class="den-rug"></div><div class="den-dragon" aria-label="Smok Pikuś">🐉</div><div class="den-floor">${DECOR[w.placed.floor]?.[0]||''}</div></div><div class="world-actions"><button class="small" data-world="feed">🍎 Poczęstuj</button><button class="small" data-world="pet">💛 Pogłaszcz</button><button class="small" data-world="play">🎵 Pobaw się</button></div><p class="den-message" role="status">${esc(message||'Pikuś zawsze się cieszy, kiedy go odwiedzasz.')}</p><section class="panel"><h2>Moje dekoracje</h2><p>Dotknij przedmiotu, aby ustawić go w domku.</p><div class="decor-grid">${DECOR.slice(0,w.unlocked).map(([ico,n],i)=>`<button class="small decor" data-world="decor" data-i="${i}"><span>${ico}</span>${n}</button>`).join('')}</div><p class="sub">Nowe ozdoby można odkryć podczas wypraw i misji. Pikuś nie potrzebuje codziennej opieki.</p></section><div class="world-actions"><button class="primary" data-world="map">🗺️ Wróć na mapę</button></div>`}
function chooseMission(kind){const w=worldData();const pool=MISSIONS.filter(m=>!kind||m.kind===kind);let options=pool.filter(m=>!w.recent.includes(m.id));if(!options.length)options=pool.filter(m=>m.id!==w.recent.at(-1));const m=pick(options.length?options:pool);w.active=m.id;w.recent=[...w.recent,m.id].slice(-20);save();missionBoard(true)}
function missionBoard(speak=false){otherScreen('mission');const w=worldData();const m=MISSIONS[w.active];if(!m||w.active===null){app.innerHTML=top()+`<section class="world-head"><h1>🌟 Misje poza ekranem</h1><p>Lula ma pomysł na zabawę w prawdziwym świecie. Wybierz przygodę!</p></section><section class="mission-intro">${puppet()}<button class="primary" data-world="randomMission">🎲 Zaskocz mnie!</button></section><div class="mission-cats">${MISSION_TYPES.map(([id,ico,title])=>`<button class="small" data-world="chooseMission" data-kind="${id}"><span>${ico}</span>${title}</button>`).join('')}</div><p class="foot">Odkryte misje: ${w.missionsDone.length} · Możesz przerwać w dowolnym momencie.</p><button class="small" data-world="map">🗺️ Mapa świata</button>`;return}app.innerHTML=top()+`<section class="panel mission-card"><div class="mission-sign">🌿 MISJA POZA EKRANEM</div><div class="mission-pic">${m.icon}</div><h1>${esc(m.title)}</h1><p class="mission-materials">🎒 ${esc(m.materials)}</p><p class="mission-instruction">${esc(m.speech)}</p><button class="small" data-world="listenMission">🔊 Posłuchaj Luli</button><div class="mission-away"><strong>Teraz czas na zabawę poza ekranem!</strong><p>Wróć razem z rodzicem, kiedy będziesz gotowa. Nie ma zegara i nie trzeba być idealną.</p></div><button class="primary" data-world="approve">🤝 Wróciłam z rodzicem</button><div class="world-actions"><button class="small" data-world="cancelMission">Inna misja ↪</button><button class="small" data-act="home">Na później 🏠</button></div><div id="missionApproval"></div></section>`;if(speak)say(m.speech)}
function askApproval(){const m=MISSIONS[worldData().active];if(!m)return;const el=$('#missionApproval');el.innerHTML=`<div class="approval"><h2>Strefa rodzica</h2><p>Czy wspólnie wykonaliście misję lub córka spróbowała ją zrealizować? Nie trzeba oceniać efektu.</p><button class="primary" data-world="confirmMission">✅ Potwierdzam jako rodzic</button><button class="small" data-world="closeApproval">Jeszcze się bawimy</button></div>`;el.scrollIntoView({block:'nearest'})}
function approveMission(){const w=worldData();if(screen!=='mission'||!$('#missionApproval .approval')||w.active===null||!MISSIONS[w.active])return;const m=MISSIONS[w.active];w.active=null;w.missionsDone.push(m.id);const prize=gift();save();otherScreen('missionDone');app.innerHTML=top()+`<section class="panel finish"><div class="pic">🎉🐉</div><h1>Misja odkryta!</h1><p>Udało wam się razem stworzyć coś w prawdziwym świecie.</p>${prize?`<div class="den-message">${prize[0]} Nowa ozdoba do domku: ${prize[1]}!</div>`:''}<div class="world-actions"><button class="primary" data-world="den">🏡 Odwiedź Pikusia</button><button class="small" data-world="missions">🌟 Wybierz inną misję</button><button class="small" data-act="home">🏠 Menu</button></div></section>`;say('Brawo!')}
function worldClick(d){const w=worldData();switch(d.world){case'map':worldMap();break;case'den':den();break;case'missions':missionBoard();break;case'randomMission':if(w.active===null)chooseMission();break;case'chooseMission':if(w.active===null)chooseMission(d.kind);break;case'cancelMission':w.active=null;save();missionBoard();break;case'listenMission':if(w.active!==null&&MISSIONS[w.active])say(MISSIONS[w.active].speech,true);break;case'approve':askApproval();break;case'closeApproval':$('#missionApproval').innerHTML='';break;case'confirmMission':approveMission();break;case'decor':{const i=Number(d.i),item=DECOR[i];if(item&&i<w.unlocked&&i>=0){w.placed[item[2]]=i;save();den('Nowa dekoracja: '+item[1]+'!')}break}case'feed':den('Mniam! Dziękuję za poczęstunek!');soundNote(440);break;case'pet':den('Pikuś merda ogonkiem! 💛');soundNote(523);break;case'play':den('Pikuś tańczy! 🎵');[262,330,392,523].forEach((f,i)=>soundNote(f,i*.22));break;}}

// Board games: voluntary language exposure, no gatekeeping questions.
GAMES.push({id:'tic',name:'Trzy w rzędzie',icon:'❎',desc:'Kółko i krzyżyk z Lulą lub tatą',color:'#e7d9fa',ink:'#594080'},{id:'ludo',name:'Wyścig do domku',icon:'🎲',desc:'Mały chińczyk dla dwojga',color:'#ffdfac',ink:'#76501c'});
const TICTHEMES=[['⭕','❌','Klasyka'],['🦊','🐰','Zwierzątka'],['M','A','Literki'],['MA','LA','Sylaby'],['KO','TA','Sylaby'],['DO','MO','Sylaby'],['KOT','DOM','Słowa'],['LAS','SER','Słowa']];
const BOARD_WORDS=[['KOT','🐈'],['DOM','🏠'],['LAS','🌲'],['SER','🧀'],['LIS','🦊'],['SOWA','🦉'],['MAPA','🗺️'],['LUPA','🔎'],['LODY','🍦'],['MAMA','👩'],['TATA','👨'],['RAK','🦞'],['RYBA','🐟'],['AUTO','🚗'],['KURA','🐔'],['PIES','🐕']];
const TICTRIPLES=[[0,1,2],[3,4,5],[6,7,8],[0,3,6],[1,4,7],[2,5,8],[0,4,8],[2,4,6]];
const LOOP=[...range(0,5).map(c=>[0,c]),...range(0,5).map(r=>[r,6]),...range(0,5).map(i=>[6,6-i]),...range(0,5).map(i=>[6-i,0])];
// Clockwise perimeter includes all 24 unique cells; opposing starts are 12 steps apart.
const DIE=['','⚀','⚁','⚂','⚃','⚄','⚅'];
let tabletop=null;
function boardMenu(kind){otherScreen('boardMenu');tabletop={kind,mode:'bot',theme:kind==='tic'?2:1};boardSetup()}
function boardSetup(){const b=tabletop,t=b.kind==='tic';app.innerHTML=top()+`<section class="panel board-setup"><div class="board-mascot">${t?'🦊 ❎':'🐰 🎲'}</div><h1>${t?'Trzy w rzędzie':'Wyścig do domku'}</h1><p>${t?'Zbuduj linię z trzech takich samych znaków!':'Doprowadź dwa pionki do domku. Rzuć kostką i wybierz pionek.'}</p><h2>Z kim grasz?</h2><div class="board-selection"><button class="small" data-board="mode" data-value="bot" aria-pressed="${b.mode==='bot'}">🐰 Z Lulą</button><button class="small" data-board="mode" data-value="local" aria-pressed="${b.mode==='local'}">👨‍👧 Z rodzicem</button></div><h2>Wybierz planszę</h2><div class="board-selection">${(t?[['0','⭕ ❌','Klasyka'],['1','🦊 🐰','Zwierzątka'],['2','M A','Litery'],['3','MA LA','Sylaby'],['6','KOT DOM','Słowa']]:[['0','🎲','Klasyka'],['1','🔎','Słowa-skarby']]).map(([i,ico,n])=>`<button class="small board-option" data-board="theme" data-value="${i}" aria-pressed="${(t?(b.theme>=3&&b.theme<=5?3:b.theme>=6?6:b.theme):b.theme)===+i}"><strong>${ico}</strong>${n}</button>`).join('')}</div><p class="sub">${t?'Znaki można usłyszeć, ale nie trzeba ich czytać, żeby wygrać.':'Krótki wariant dla dwojga: każdy ma dwa pionki, nie czekamy na szóstkę, a nadmiar oczek nie blokuje mety.'}</p><button class="primary" data-board="begin">▶ Zagraj!</button></section>`;updateAtSafePoint()}
function boardBegin(){const prev=tabletop;otherScreen('board');const b=tabletop={kind:prev.kind,mode:prev.mode,theme:prev.theme,turn:0,ended:false,busy:false,round:0};if(b.kind==='tic'){b.cells=Array(9).fill(null);b.win=[];b.symbols=TICTHEMES[b.theme].slice(0,2)}else{b.positions=[[-1,-1],[-1,-1]];b.die=0;b.phase='roll';const words=shuffle(BOARD_WORDS);b.words=Object.fromEntries(shuffle(range(0,23).filter(i=>i!==0&&i!==12)).slice(0,8).map((i,j)=>[i,words[j]]));b.lastWord=null;b.note='Rzuć kostką!'}boardRender();say(b.kind==='tic'?'Ułóż trzy znaki w jednej linii.':'Rzuć kostką i wybierz pionek.')}
function boardName(p){return p===0?'Odkrywczyni':tabletop.mode==='bot'?'Lula':'Rodzic'}
function boardDelay(fn,ms){const t=token;clearTimeout(timer);timer=setTimeout(()=>{if(t===token&&screen==='board'&&!tabletop.ended)fn()},ms)}
function boardBot(){const b=tabletop;if(b.ended||b.mode!=='bot'||b.turn!==1)return;boardDelay(()=>{if(b.kind==='tic'){const free=range(0,8).filter(i=>b.cells[i]===null);const would=p=>free.find(i=>{let c=b.cells.slice();c[i]=p;return TICTRIPLES.some(row=>row.every(j=>c[j]===p))});const win=would(1),block=would(0);ticMove(win??(Math.random()<.76?block:undefined)??pick(free))}else if(b.phase==='roll')ludoRoll();else if(b.phase==='move'){const avail=ludoAvailable();ludoMove(avail.sort((a,c)=>b.positions[1][c]-b.positions[1][a])[0])}},b.kind==='tic'?650:900)}
function boardEnd(winner){const b=tabletop;if(b.ended)return;b.ended=true;b.winner=winner;b.busy=false;screen='boardDone';const s=store.stats[b.kind]||{done:0,help:0};s.done++;store.stats[b.kind]=s;store.lastGame=b.kind;b.prize=gift();save();boardRender();say(winner===null?'Super! Remis. Dobra zabawa!':winner===0?'Brawo! Udało się!':'Świetna wspólna gra!');updateAtSafePoint();void checkForUpdates()}
function ticMove(i){const b=tabletop;if(b.ended||b.cells[i]!==null)return;const p=b.turn;b.cells[i]=p;const row=TICTRIPLES.find(row=>row.every(j=>b.cells[j]===p));if(row){b.win=row;boardEnd(p);return}if(b.cells.every(x=>x!==null)){boardEnd(null);return}if(b.theme>=2){const s=b.symbols[p];say(s.length===1?({M:'em',A:'a'}[s]||s.toLowerCase()):s.toLowerCase())}b.turn=1-p;boardRender();boardBot()}
function ludoIndex(p,progress){return (p*12+progress)%24}
function ludoAvailable(){return range(0,1).filter(i=>tabletop.positions[tabletop.turn][i]<24)}
function ludoRoll(){const b=tabletop;if(b.ended||b.phase!=='roll'||b.busy)return;b.busy=true;b.phase='rolling';b.die=1+Math.floor(Math.random()*6);b.note='🎲 Kostka się toczy…';boardRender();boardDelay(()=>{b.busy=false;b.phase='move';b.note=`Wypadło ${b.die}. Wybierz pionek!`;boardRender();say(String(b.die));boardBot()},380)}
function ludoMove(i){const b=tabletop;if(b.ended||b.phase!=='move'||b.busy||!ludoAvailable().includes(i))return;const p=b.turn,old=b.positions[p][i],end=Math.min(24,old+b.die);b.busy=true;b.phase='moving';let current=old;b.note='Pionek w drodze!';function step(){current++;b.positions[p][i]=current;boardRender();if(current<end){boardDelay(step,170);return}b.busy=false;b.lastWord=null;let note='';if(current<24){const ix=ludoIndex(p,current),other=b.positions[1-p];if(ix!==0&&ix!==12){for(let j=0;j<2;j++)if(other[j]>=0&&other[j]<24&&ludoIndex(1-p,other[j])===ix){other[j]=-1;note='Spotkanie pionków! Drugi wraca na start. ';}}if(b.theme&&b.words[ix]){b.lastWord=b.words[ix];say(b.lastWord[0].toLowerCase());store.treasures=unique([...(store.treasures||[]),b.lastWord[0]]);save()}}else note='🏡 Pionek dotarł do domku! ';if(b.positions[p].every(v=>v===24)){boardEnd(p);return}if(b.die!==6)b.turn=1-p;else note+='Szóstka! Jeszcze jeden rzut. ';b.phase='roll';b.note=note+'Rzuć kostką!';boardRender();boardBot()}boardDelay(step,150)}
function boardRender(){const b=tabletop,t=b.kind==='tic',human=!(b.mode==='bot'&&b.turn===1),names=[boardName(0),boardName(1)];let body='';if(t){body=`<div class="tic-board">${b.cells.map((p,i)=>`<button class="tic-cell ${b.win.includes(i)?'tic-win':''} ${p===null?'':`player-${p}`}" data-board="tic" data-i="${i}" aria-label="Pole ${i+1}${p===null?', puste':', '+esc(b.symbols[p])}" ${b.ended||p!==null||!human?'disabled':''}>${p===null?'':esc(b.symbols[p])}</button>`).join('')}</div><div class="board-legend">${b.symbols.map((s,i)=>`<button class="small player-${i}" data-board="speak" data-value="${esc(s)}">${esc(s)} · ${names[i]}</button>`).join('')}</div>`}else{const cells=LOOP.map(([r,c],ix)=>{const pawns=[];for(let p=0;p<2;p++)for(let j=0;j<2;j++){let v=b.positions[p][j];if(v>=0&&v<24&&ludoIndex(p,v)===ix)pawns.push(`<span class="race-pawn player-${p}">${p?'🐰':'🦊'}<small>${j+1}</small></span>`)}const word=b.theme?b.words[ix]:null;return `<button class="race-cell ${ix===0?'start-a':ix===12?'start-b':''}" style="grid-row:${r+1};grid-column:${c+1}" ${word?`data-board="speak" data-value="${word[0]}" aria-label="Pole ${ix+1}: ${word[0]}"`:`disabled aria-label="Pole ${ix+1}"`}><span class="cell-label">${ix===0?'🚩':ix===12?'🏁':word?word[1]:ix+1}</span>${word?`<span class="cell-word">${word[0]}</span>`:''}<span class="race-stack">${pawns.join('')}</span></button>`}).join('');body=`<div class="race-board">${cells}<div class="race-center"><div>🏡</div><strong>DOM</strong><span>🦊 ${b.positions[0].filter(v=>v===24).length}/2 · 🐰 ${b.positions[1].filter(v=>v===24).length}/2</span><button class="race-die ${b.phase==='rolling'?'rolling':''}" data-board="roll" ${!human||b.phase!=='roll'||b.ended?'disabled':''} aria-label="Rzuć kostką">${DIE[b.die]||'🎲'}</button><small>${b.die?`Wynik: ${b.die}`:'Rzuć kostką'}</small></div></div><div class="race-controls">${[0,1].map(p=>`<div class="race-player player-${p}"><strong>${p?'🐰':'🦊'} ${names[p]}</strong><div>${b.positions[p].map((v,i)=>`<button class="small" data-board="pawn" data-i="${i}" ${!human||b.turn!==p||b.phase!=='move'||v===24||b.ended?'disabled':''}>${p?'🐰':'🦊'} ${i+1} ${v===24?'🏡':v===-1?'🚩':`${v+1}/24`}</button>`).join('')}</div></div>`).join('')}</div><p class="board-note" role="status">${esc(b.note)}</p>${b.lastWord?`<button class="small board-found" data-board="speak" data-value="${b.lastWord[0]}">${b.lastWord[1]} ${b.lastWord[0]} 🔊</button>`:''}`}
app.innerHTML=top()+`<section class="panel tabletop"><div class="board-head"><div><h1>${t?'❎ Trzy w rzędzie':'🎲 Wyścig do domku'}</h1><p class="board-turn" role="status">${b.ended?(b.winner===null?'Remis! 🎉':`${boardName(b.winner)} wygrywa! 🎉`):`Teraz: ${t?b.symbols[b.turn]:b.turn?'🐰':'🦊'} ${boardName(b.turn)}${human?'':' · myśli…'}`}</p></div><button class="small" data-board="menu">⚙️ Wybór gry</button></div>${body}${b.ended?`<div class="board-end"><strong>Super, że graliśmy razem!</strong>${b.prize?`<p>${b.prize[0]} Nowa ozdoba do domku: ${b.prize[1]}</p>`:''}<button class="primary" data-board="again">🔄 Jeszcze raz</button></div>`:''}<p class="sub">${t?'Trzy znaki w pionie, poziomie lub po skosie.':'Zbieraj słowa po drodze. Dwa pionki w domku kończą wyścig.'}</p><div class="actions"><button class="small" data-board="change">🗺️ Inna plansza</button><button class="small" data-world="missions">🌟 Zabawa poza ekranem</button></div></section><p id="updateNotice" class="hint" role="status" hidden></p>`;updateUI()}
function boardClick(d){const b=tabletop;if(!b)return;switch(d.board){case'mode':if(screen==='boardMenu'){b.mode=d.value;boardSetup()}break;case'theme':if(screen==='boardMenu'){const v=+d.value;b.theme=b.kind==='tic'&&v===3?pick([3,4,5]):b.kind==='tic'&&v===6?pick([6,7]):v;boardSetup()}break;case'begin':case'again':boardBegin();break;case'menu':case'change':boardMenu(b.kind);break;case'speak':{const v=d.value;say(v==='M'?'em':v.toLowerCase(),true);break}case'tic':if(!b.ended&&!(b.mode==='bot'&&b.turn===1))ticMove(+d.i);break;case'roll':if(!(b.mode==='bot'&&b.turn===1))ludoRoll();break;case'pawn':if(!(b.mode==='bot'&&b.turn===1))ludoMove(+d.i);break}}

// Four family games: visual matching, counting and spatial orientation.
const EXTRA_GAMES=[
{id:'ladders',name:'Węże i drabiny',icon:'🪜',desc:'Wspinaj się do zamku',color:'#d4edb0',ink:'#375d29'},
{id:'domino',name:'Domino odkrywców',icon:'🧩',desc:'Połącz obrazki i słowa',color:'#f9dfab',ink:'#754d19'},
{id:'pirates',name:'Wyspa piratów',icon:'🏴‍☠️',desc:'Odkrywaj skrzynie na mapie',color:'#cbe9f8',ink:'#255675'},
{id:'spot',name:'Bystre oko',icon:'👀',desc:'Znajdź wspólny obrazek',color:'#f2dafa',ink:'#713c82'}];
GAMES.push(...EXTRA_GAMES);
const EXTRA_IDS=EXTRA_GAMES.map(g=>g.id), FAMILY_IDS=['tic','ludo',...EXTRA_IDS];
const EXTRA_WORDS=BOARD_WORDS.filter(([w])=>w!=='PIES');
const EXTRA_WORD=Object.fromEntries(EXTRA_WORDS);
const EXTRA_RULES={ladders:'Rzuć kostką. Drabina pomaga wejść wyżej, a wąż zjeżdża kawałek w dół. Kto pierwszy dotrze do zamku?',domino:'Połącz koniec domina z takim samym obrazkiem. Możesz dotknąć całego klocka. Ułóżmy wszystkie!',pirates:'Wybieraj pola na mapie. W piasku ukryto pięć skarbów. Odnajdźmy je razem!',spot:'Na obu kartach jest tylko jeden taki sam obrazek. Dotknij go na dolnej karcie!'};
let extra=null;
function extraMenu(kind){otherScreen('extraMenu');extra={kind,mode:['ladders','pirates'].includes(kind)?'bot':'solo',words:true};extraSetup()}
function extraSetup(){const e=extra,g=EXTRA_GAMES.find(g=>g.id===e.kind);let modes=['ladders','pirates'].includes(e.kind)?[['bot','🐰 Z Lulą'],['local','👨‍👧 Z rodzicem']]:[['solo','🦊 Samodzielnie'],['local','👨‍👧 Razem']];app.innerHTML=top()+`<section class="panel board-setup"><div class="board-mascot">${g.icon}</div><h1>${g.name}</h1><p>${EXTRA_RULES[e.kind]}</p><h2>Jak gramy?</h2><div class="board-selection">${modes.map(([v,n])=>`<button class="small" data-extra="mode" data-v="${v}" aria-pressed="${e.mode===v}">${n}</button>`).join('')}</div><div class="board-selection"><button class="small" data-extra="words" data-v="0" aria-pressed="${!e.words}">🖼️ Same obrazki</button><button class="small" data-extra="words" data-v="1" aria-pressed="${e.words}">🔤 Obrazki i słowa</button></div><button class="small" data-extra="rules">🔊 Posłuchaj zasad</button><button class="primary" data-extra="begin">▶ Zagraj!</button></section>`;updateAtSafePoint()}
function extraBegin(){const {kind,mode,words}=extra;otherScreen('extraPlay');extra={kind,mode,words,turn:0,ended:false,busy:false,note:'',round:0,found:[],wrong:null};const e=extra;
 if(kind==='ladders'){e.pos=[1,1];e.die=0;e.jumps=pick([{3:9,8:14,13:19,17:11,23:20},{4:10,7:13,15:21,18:12,24:19},{2:8,6:12,14:20,16:10,23:18}]);const labels=shuffle(EXTRA_WORDS);e.labels=Object.fromEntries(shuffle(range(2,24)).slice(0,6).map((i,j)=>[i,labels[j][0]]));e.note='Rzuć kostką!'}
 if(kind==='domino'){let a=shuffle(EXTRA_WORDS.map(x=>x[0])).slice(0,7);e.end=a[0];e.chain=[a[0]];e.tiles=shuffle(a.slice(1).map((v,i)=>({id:i,values:Math.random()<.5?[a[i],v]:[v,a[i]]})));e.note='Znajdź pasujący klocek.'}
 if(kind==='pirates'){const loot=shuffle(EXTRA_WORDS);e.chests=Object.fromEntries(shuffle(range(0,24)).slice(0,5).map((i,j)=>[i,loot[j][0]]));e.opened=[];e.count=[0,0];e.note='Wybierz pole na mapie.';e.last=null}
 if(kind==='spot'){e.total=5;spotRound()}
 extraRender();say(EXTRA_RULES[kind]);}
function extraName(p=extra.turn){return p===0?'Odkrywczyni':extra.mode==='bot'?'Lula':'Rodzic'}
function extraHuman(){return !(extra.mode==='bot'&&extra.turn===1)}
function extraDelay(fn,ms){const t=token,e=extra;clearTimeout(timer);timer=setTimeout(()=>{if(t===token&&screen==='extraPlay'&&e===extra&&!e.ended)fn()},ms)}
function extraCollect(w){if(!w)return;collectWord(w);say(w.toLowerCase())}
function extraEnd(note){let e=extra;if(e.ended)return;e.ended=true;e.busy=false;e.note=note;screen='extraDone';const s=store.stats[e.kind]||{done:0,help:0};s.done++;store.stats[e.kind]=s;store.lastGame=e.kind;e.prize=gift();save();extraRender();say('Świetna wspólna gra!');updateAtSafePoint();void checkForUpdates()}
function extraTurn(){const e=extra;e.busy=false;e.turn=1-e.turn;extraRender();if(e.mode==='bot'&&e.turn===1)extraDelay(()=>{if(e.kind==='ladders')ladderRoll();else if(e.kind==='pirates')pirateOpen(pick(range(0,24).filter(i=>!e.opened.includes(i))))},750)}
function ladderRoll(){const e=extra;if(e.busy||e.ended)return;e.busy=true;e.die=1+Math.floor(Math.random()*6);e.note='Kostka: '+e.die;extraRender();say(String(e.die));const p=e.turn,target=Math.min(25,e.pos[p]+e.die);function step(){if(e.pos[p]<target){e.pos[p]++;extraRender();extraDelay(step,145);return}const jump=e.jumps[target];if(jump){e.pos[p]=jump;e.note=jump>target?'🪜 Drabina! W górę!':'🐍 Zjazd po wężu!';extraRender()}const end=e.pos[p];if(end===25){extraEnd(p===0?'Dotarłaś do zamku! 🎉':`${extraName(p)} dotarł(a) do zamku! 🎉`);return}if(e.words&&e.labels[end])extraCollect(e.labels[end]);extraDelay(extraTurn,jump?850:450); // prevent a second roll before the turn changes
 }extraDelay(step,300)}
// Release the turn lock only when the animated move is finished.
function dominoPlace(i){const e=extra;if(e.ended||e.busy)return;const tile=e.tiles.find(t=>t.id===i);if(!tile)return;if(!tile.values.includes(e.end)){e.wrong=i;e.note='Poszukaj tego samego obrazka.';extraRender();return}const next=tile.values[0]===e.end?tile.values[1]:tile.values[0];e.tiles=e.tiles.filter(t=>t.id!==i);e.chain.push(next);e.end=next;e.wrong=null;if(e.words)extraCollect(next);if(!e.tiles.length){extraEnd('Cały łańcuch ułożony! 🎉');return}e.note='Pasuje! Który klocek będzie następny?';if(e.mode==='local')e.turn=1-e.turn;extraRender()}
function pirateOpen(i){const e=extra;if(e.ended||e.busy||e.opened.includes(i)||i<0||i>24)return;e.opened.push(i);const w=e.chests[i];const coord='ABCDE'[i%5]+(Math.floor(i/5)+1);e.last=w||null;if(w){e.found.push(w);e.count[e.turn]++;e.note=coord+' · Skarb! '+(e.words?w:'');if(e.words)extraCollect(w)}else{e.note=coord+' · Tu jest tylko piasek.';say(coord)}if(e.found.length===5){extraEnd('Wszystkie skarby odkryte! 🎉');return}e.busy=true;extraRender();extraDelay(extraTurn,720)}
function spotRound(){const e=extra,a=shuffle(EXTRA_WORDS.map(x=>x[0]));e.common=a[0];e.cards=[shuffle(a.slice(0,5)),shuffle([a[0],...a.slice(5,9)])];e.wrong=null;e.note='Co jest na obu kartach?';e.busy=false;e.correct=false}
function spotPick(w){const e=extra;if(e.ended||e.busy||!e.cards[1].includes(w))return;if(w!==e.common){e.wrong=w;e.note='Spójrz jeszcze raz na obie karty.';extraRender();return}e.round++;e.correct=true;e.busy=true;e.wrong=null;e.note='Jest para!';if(e.words)extraCollect(w);else say('Brawo!');extraRender()}
function spotNext(){const e=extra;if(!e.correct||e.ended)return;if(e.round===e.total){extraEnd('Wszystkie pary odnalezione! 🎉');return}if(e.mode==='local')e.turn=1-e.turn;spotRound();extraRender()}
function ew(w){return `<span class="ew-icon">${EXTRA_WORD[w]}</span>${extra.words?`<span class="ew-word">${w}</span>`:''}`}
function extraRender(){const e=extra,g=EXTRA_GAMES.find(g=>g.id===e.kind);let body='';const lock=e.ended||e.busy||!extraHuman();
 if(e.kind==='ladders'){const cells=range(1,25).map(n=>{const row=Math.floor((n-1)/5),col=(n-1)%5,c=row%2?4-col:col;const jump=e.jumps[n],label=e.words?e.labels[n]:null;return `<div class="ladder-cell ${jump?(jump>n?'up':'down'):''} ${n===25?'goal':''}" style="grid-row:${5-row};grid-column:${c+1}"><b>${n===25?'🏰':n}</b>${jump?`<span class="ladder-jump">${jump>n?'🪜':'🐍'} ${jump>n?'↗':'↘'} ${jump}</span>`:label?`<span class="ladder-label">${EXTRA_WORD[label]} ${label}</span>`:''}<div class="ladder-pawns">${e.pos.map((v,i)=>v===n?`<span>${i?'🐰':'🦊'}</span>`:'').join('')}</div></div>`}).join('');body=`<div class="ladder-board">${cells}</div><div class="extra-controls"><button class="primary extra-die" data-extra="roll" ${lock?'disabled':''}>${DIE[e.die]||'🎲'} Rzuć kostką</button><span>🦊 ${e.pos[0]} · 🐰 ${e.pos[1]}</span></div>`}
 if(e.kind==='domino'){body=`<div class="domino-chain" aria-label="Łańcuch domina">${e.chain.map(w=>`<span>${EXTRA_WORD[w]}</span>`).join('<small>–</small>')}</div><div class="domino-target"><span>Połącz z:</span><button class="small ew" data-extra="say" data-v="${e.end}">${ew(e.end)}</button></div><div class="domino-hand">${e.tiles.map(t=>`<button class="domino-tile ${e.wrong===t.id?'retry':''}" data-extra="tile" data-i="${t.id}" ${e.ended?'disabled':''}>${t.values.map(w=>`<span class="ew">${ew(w)}</span>`).join('')}</button>`).join('')}</div>`}
 if(e.kind==='pirates'){body=`<div class="pirate-map"><div></div>${[...'ABCDE'].map(c=>`<b>${c}</b>`).join('')}${range(0,4).map(r=>`<b>${r+1}</b>${range(0,4).map(c=>{const i=r*5+c,opened=e.opened.includes(i),w=e.chests[i];return `<button class="pirate-cell ${opened?'opened':''} ${opened&&w?'chest':''}" data-extra="dig" data-i="${i}" aria-label="${'ABCDE'[c]}${r+1}${opened?', odkryte':''}" ${opened||lock?'disabled':''}>${opened?(w?'💎':'·'):['🌴','🌿','🐚','🍄','🌱'][i%5]}</button>`}).join('')}`).join('')}</div><div class="pirate-loot">${e.found.map(w=>`<button class="small ew" data-extra="say" data-v="${w}">${ew(w)}</button>`).join('')}<strong>🧰 ${e.found.length}/5</strong></div>`}
 if(e.kind==='spot'){body=`<div class="spot-progress">${e.round}/${e.total} par ⭐</div><div class="spot-card spot-top">${e.cards[0].map(w=>`<div class="ew ${e.correct&&w===e.common?'spot-ok':''}">${ew(w)}</div>`).join('')}</div><div class="spot-card spot-bottom">${e.cards[1].map(w=>`<button class="ew ${e.correct&&w===e.common?'spot-ok':''} ${e.wrong===w?'retry':''}" data-extra="spot" data-v="${w}" ${e.busy||e.ended?'disabled':''}>${ew(w)}</button>`).join('')}</div>${e.correct&&!e.ended?'<button class="primary" data-extra="spotNext">Dalej ➜</button>':''}`}
 const turn=e.mode==='solo'?'':`${extraName()} · `;app.innerHTML=top()+`<section class="panel extra-panel"><div class="board-head"><div><h1>${g.icon} ${g.name}</h1><p class="board-turn">${e.ended?'🎉 Wyprawa zakończona':turn+(e.kind==='pirates'?'Szukamy razem':'Twoja kolej')}</p></div><button class="small" data-extra="menu">⚙️</button></div>${body}<p class="board-note" role="status">${esc(e.note)}</p>${e.ended?`<div class="board-end">${e.prize?`<p>${e.prize[0]} Ozdoba: ${e.prize[1]}</p>`:''}<button class="primary" data-extra="begin">🔄 Jeszcze raz</button></div>`:''}<div class="actions"><button class="small" data-extra="rules">🔊 Zasady</button><button class="small" data-act="home">🏠 Inna gra</button></div></section><p id="updateNotice" class="hint" role="status" hidden></p>`;updateUI()}
function extraClick(d){const e=extra;if(!e)return;switch(d.extra){case'menu':extraMenu(e.kind);break;case'mode':if(screen==='extraMenu'){e.mode=d.v;extraSetup()}break;case'words':if(screen==='extraMenu'){e.words=d.v==='1';extraSetup()}break;case'rules':say(EXTRA_RULES[e.kind],true);break;case'begin':extraBegin();break;case'say':say(d.v.toLowerCase(),true);break;case'roll':if(extraHuman())ladderRoll();break;case'tile':dominoPlace(+d.i);break;case'dig':if(extraHuman())pirateOpen(+d.i);break;case'spot':spotPick(d.v);break;case'spotNext':spotNext();break}}

// Active adventures: movement, make-believe, collecting and off-screen play.
const ACTIVE_GAMES=[
{id:'island',name:'Piracka Wyspa Literek',icon:'🏴‍☠️',desc:'Chodź po wyspie i zbieraj litery',color:'#bfe9dd',ink:'#235a51'},
{id:'rally',name:'Rajd samochodowy',icon:'🏎️',desc:'Jedź po literki i omijaj przeszkody',color:'#d9e4ff',ink:'#364c83'},
{id:'pizza',name:'Pizzeria Luli',icon:'🍕',desc:'Przygotuj zamówienia zwierzaków',color:'#ffdfb2',ink:'#83481e'},
{id:'fishing',name:'Magiczne łowienie',icon:'🎣',desc:'Rybki, skarby i ukryte słowa',color:'#bceaf9',ink:'#235c7c'},
{id:'freeze',name:'Tańcz i zamarznij',icon:'💃',desc:'Tańcz, słuchaj i zamieniaj się w posąg',color:'#f7cfe8',ink:'#843a72'}];
GAMES.unshift(...ACTIVE_GAMES);
const ACTIVE_IDS=ACTIVE_GAMES.map(g=>g.id);
const ISLAND_WORDS=[['KOT','🐈'],['DOM','🏠'],['LAS','🌲'],['NOS','👃'],['BUT','👟'],['SER','🧀'],['RAK','🦞'],['LEW','🦁'],['LIS','🦊'],['RYBA','🐟'],['SOWA','🦉'],['MAMA','👩'],['TATA','👨'],['LALA','🪆'],['MAPA','🗺️'],['AUTO','🚗'],['LODY','🍦'],['PUMA','🐆'],['KURA','🐔'],['KOZA','🐐'],['WODA','💧'],['OKO','👁️'],['LATO','☀️'],['BALON','🎈']];
const REWARD_SET={island:[['🐚','Muszla piratki'],['🦜','Papuga'],['⚓','Kotwica'],['🗺️','Mapa wyspy'],['🏝️','Model wyspy']],rally:[['🏁','Flaga mety'],['🚗','Miniaturowe auto'],['🏎️','Rajdówka'],['🛞','Złote koło'],['🏆','Puchar kierowcy']],pizza:[['🍅','Złoty pomidor'],['🧑‍🍳','Czapka kucharska'],['🍕','Pizza Luli'],['🧀','Skarb serowy'],['📒','Książka przepisów']],fishing:[['🐠','Kolorowa rybka'],['🐙','Ośmiornica'],['🪸','Koral'],['🐬','Delfin'],['🐳','Wieloryb']],freeze:[['🎵','Nuta'],['🥁','Bębenek'],['🎸','Gitara'],['🎀','Kokarda taneczna'],['🎤','Mikrofon']],other:[['🌻','Kwiat odkrywcy'],['🪁','Latawiec'],['🧩','Puzzle'],['🦋','Motyl'],['🔭','Luneta'],['🚀','Rakieta']]};
function rewardData(){if(!store.album||typeof store.album!=='object')store.album={counts:{},total:0};return store.album}
function awardAlbum(kind){const a=rewardData(),k=REWARD_SET[kind]?kind:'other',prev=a.counts[k]||0;a.counts[k]=prev+1;a.total++;return REWARD_SET[k][prev]||null}
function rewardAlbum(){otherScreen('album');const a=rewardData();app.innerHTML=top()+`<section class="panel active-panel"><h1>🎁 Album skarbów</h1><p>Twoje odkrycia: <strong>${a.total}</strong> ⭐</p><p>Każda wyprawa to nowa przygoda. Skarby nigdy nie znikają.</p>${Object.entries(REWARD_SET).map(([k,items])=>`<h2 class="album-title">${GAMES.find(g=>g.id===k)?.name||'Inne wyprawy'}</h2><div class="album-grid">${items.map(([ico,n],i)=>`<div class="album-card ${i<(a.counts[k]||0)?'unlocked':''}"><span>${i<(a.counts[k]||0)?ico:'🎁'}</span><strong>${i<(a.counts[k]||0)?n:'Niespodzianka'}</strong></div>`).join('')}</div>`).join('')}<div class="actions"><button class="primary" data-act="home">🗺️ Inna przygoda</button></div></section>`}
let adv=null, advTimers=[];
function advClear(){for(const id of advTimers)clearTimeout(id);advTimers=[]}
function advLater(fn,ms){const a=adv,t=token;const id=setTimeout(()=>{advTimers=advTimers.filter(x=>x!==id);if(screen==='active'&&a===adv&&t===token)fn()},ms);advTimers.push(id)}
function advWord(k){const recent=store.history[k]||[];const w=pick(ISLAND_WORDS.filter(([s])=>!recent.includes(s)).length?ISLAND_WORDS.filter(([s])=>!recent.includes(s)):ISLAND_WORDS);store.history[k]=[...recent,w[0]].slice(-15);save();return w}
function advStart(kind,long=false){otherScreen('active');const a=adv={kind,note:'',busy:false,goal:kind==='pizza'?(long?5:3):kind==='fishing'?(long?8:5):kind==='freeze'?(long?6:4):1};
 if(kind==='island'){[a.word,a.pic]=advWord(kind);a.pos=29;a.avatar=store.pirateAvatar||'🧑‍🌾';a.items=shuffle(range(0,34).filter(i=>i!==29)).slice(0,a.word.length+4).map((pos,i)=>({pos,l:i<a.word.length?a.word[i]:pick([... 'ABEFKMNOST'].filter(c=>!a.word.includes(c))),got:false}));a.bag=[];a.assembled=[];a.phase='hunt';a.note='Dotknij miejsca na wyspie. Twój bohater tam pójdzie.';saySequence(['Znajdź litery do słowa.',a.word.toLowerCase()])}
 if(kind==='rally'){[a.word,a.pic]=advWord(kind);a.letters=[];a.lane=1;a.rows=Array.from({length:4},()=>[{},{},{}]);a.dist=0;a.running=false;a.note='Wybierz pas i ruszaj!';a.rows[0]=rallyRow();say('Zbieraj litery i omijaj przeszkody.')}
 if(kind==='pizza'){a.total=0;a.order=null;pizzaOrder();say('Przygotuj pizzę dla zwierzaka.')}
 if(kind==='fishing'){a.catches=[];a.fish=fishNew();a.note='Dotknij rybki, aby zarzucić wędkę.';say('Zarzuć wędkę i odkryj skarb.')}
 if(kind==='freeze'){a.round=0;a.phase='ready';a.beat=0;a.note='Zróbcie miejsce do tańca. Zaproś rodzica!';say('Zatańcz, a kiedy muzyka ucichnie, zatrzymaj się.')}
 advRender();}
function advEnd(){if(screen!=='active'||adv.ended)return;adv.ended=true;advClear();stopMusic();stopVoice();const a=adv;const stat=store.stats[a.kind]||{done:0,help:0};stat.done++;store.stats[a.kind]=stat;store.lastGame=a.kind;const album=awardAlbum(a.kind);const decor=gift(false);save();screen='activeDone';app.innerHTML=top()+`<section class="panel finish"><div class="pic reward-pop">${album?.[0]||'🌟'} 🎉</div><h1>Wyprawa odkryta!</h1><p class="question">${album?'Twój nowy skarb: '+album[1]:'Kolejna piękna przygoda!'}</p>${decor?`<p>${decor[0]} Ozdoba do domku: ${decor[1]}</p>`:''}<div class="actions"><button class="primary" data-active="again">Jeszcze raz ↻</button>${['pizza','fishing','freeze'].includes(a.kind)?'<button class="small" data-active="long">🌟 Dłuższa wyprawa</button>':''}<button class="small" data-active="album">🎁 Album</button><button class="small" data-world="den">🏡 Domek</button><button class="small" data-act="home">🗺️ Inna gra</button></div></section>`;say('Brawo! Odkryłaś kolejny skarb!');updateAtSafePoint();void checkForUpdates()}
function islandNeeded(a){return [...a.word].filter((l,i)=>[...a.word.slice(0,i+1)].filter(c=>c===l).length>a.bag.filter(o=>o.l===l).length)}
function islandMove(i){const a=adv;if(a.busy||a.phase!=='hunt'||i<0||i>=35)return;const step=()=>{const old=a.pos;if(old!==i){const x=old%7,y=Math.floor(old/7),tx=i%7,ty=Math.floor(i/7);a.pos= x!==tx?old+Math.sign(tx-x):old+7*Math.sign(ty-y);a.from=old;let item=a.items.find(o=>!o.got&&o.pos===a.pos);if(item){item.got=true;const need=islandNeeded(a).includes(item.l);if(need){a.bag.push(item);a.note='Masz literę '+item.l+'!';say(item.l.toLowerCase());soundNote(660)}else{a.note='To dodatkowe znalezisko! Szukamy dalej.';soundNote(392)}}if(!islandNeeded(a).length){a.phase='assemble';a.busy=false;a.note='Wszystkie litery są w sakwie! Ułóż hasło.';a.bag=shuffle(a.bag);saySequence(['Ułóż słowo z literek.',a.word.toLowerCase()]);advRender();return}advRender();advLater(step,160)}else{a.busy=false;advRender()}};a.busy=true;step()}
function islandLetter(i){const a=adv;if(a.phase!=='assemble'||a.assembled.includes(i)||!a.bag[i])return;const l=a.bag[i].l;if(l!==a.word[a.assembled.length]){a.note='Popatrz na kolejne pole w haśle. Spróbuj innej litery.';say('Spróbuj jeszcze raz.');advRender();return}a.assembled.push(i);soundNote(520+a.assembled.length*80);if(a.assembled.length===a.word.length){a.phase='chest';a.note='Hasło gotowe! Otwórz skrzynię.';collectWord(a.word);say(a.word.toLowerCase())}advRender()}
function rallyRow(){const a=adv,next=a.word?.[a.letters?.length||0]||'A';const l=pick([0,1,2]),o=pick([0,1,2].filter(i=>i!==l));return range(0,2).map(i=>i===l?{letter:next}:i===o?{obstacle:pick(['🚧','🪨','🪵'])}:{})}
function rallyTick(){const a=adv;if(!a.running||a.ended||screen!=='active')return;const hit=a.rows.pop()[a.lane];a.dist++;a.note='Jedziemy dalej!';if(hit.obstacle){a.note='Mały postój — objazd!';soundNote(220)}if(hit.letter===a.word[a.letters.length]){a.letters.push(hit.letter);a.note='Zebrana litera '+hit.letter+'!';soundNote(620);if(a.letters.length===a.word.length){a.running=false;collectWord(a.word);advRender();say(a.word.toLowerCase());return}}a.rows.unshift(rallyRow());advRender();advLater(rallyTick,hit.obstacle?1550:1000)}
const TOPPINGS=[['🍅','POMIDOR'],['🧀','SER'],['🍄','GRZYB'],['🫑','PAPRYKA'],['🌽','KUKURYDZA'],['🫒','OLIWKA']];
function pizzaOrder(){const a=adv;a.customer=pick(['🐰','🦊','🐼','🐉','🐱']);a.order=shuffle(range(0,5)).slice(0,3).map(i=>({i,n:pick([1,2,3])}));a.placed=[];a.note='Dodaj tyle składników, ile zamówił gość.'}
function fishNew(){return shuffle(ISLAND_WORDS).slice(0,6).map(([word,pic],i)=>({word,pic,fish:pick(['🐠','🐟','🐡','🦀','🐙','🐚']),id:i}))}
function fishCatch(i){const a=adv;if(a.busy||a.catches.length>=a.goal||!a.fish[i])return;a.busy=true;a.hook=i;advRender();advLater(()=>{const f=a.fish[i];a.catches.push(f);a.last=f;collectWord(f.word);a.fish=fishNew();a.busy=false;a.hook=null;a.note='Znalezisko: '+f.word+'!';say(f.word.toLowerCase());soundNote(540);advRender()},700)}
function freezeBegin(){const a=adv;advClear();stopMusic();stopVoice();a.phase='dance';a.beat=0;a.limit=pick([14,17,20,23]);a.note='Tańcz!';advRender();const notes=[262,330,392,440,392,330,294,349,440,392,330,294,262,330,392,523];function beat(){if(a.phase!=='dance')return;if(a.beat>=a.limit){a.phase='stop';a.note='STOP! Zamarznij jak posąg!';stopMusic();say('Stop! Zamarznij!');advRender();advLater(()=>{if(a.phase!=='stop')return;a.round++;if(a.round>=a.goal){a.phase='readyDone';a.note='Wspaniały taniec!';advRender()}else freezeBegin()},3200);return}soundNote(notes[a.beat%notes.length],0,.24);if(a.beat%2===0)soundNote(130.8,0,.14,'sine');a.beat++;advLater(beat,300)}beat()}
function advRender(){const a=adv,g=ACTIVE_GAMES.find(g=>g.id===a.kind);let body='';const listen=`<button class="small" data-active="listen">🔊 Posłuchaj</button>`;
 if(a.kind==='island'){const needed=a.phase==='hunt',chest=a.phase==='chest';body=`<div class="adv-target"><span>${a.pic}</span><strong>${a.word}</strong>${listen}<span class="adv-count">${a.bag.length}/${a.word.length} 🔤</span></div>${needed?`<div class="avatar-choice"><button class="small" data-active="avatar" data-v="🧑‍🌾">🧑‍🌾</button><button class="small" data-active="avatar" data-v="👩‍🦰">👩‍🦰</button><button class="small" data-active="avatar" data-v="🦊">🦊</button></div><div class="island-field"><div class="island-grid">${range(0,34).map(i=>{const item=a.items.find(o=>o.pos===i&&!o.got);return `<button class="island-cell ${i<7||i>27?'beach':''}" data-active="walk" data-i="${i}" ${a.busy?'disabled':''} aria-label="${item?'Litera '+item.l:'Idź na pole '+(i+1)}">${item?`<span class="letter-gem">${item.l}</span>`:i===a.pos?'':(i%9===0?'🌴':i%6===0?'🌺':i%11===0?'🪨':'')}</button>`}).join('')}<span class="island-avatar" style="left:${(a.pos%7+.5)*100/7}%;top:${(Math.floor(a.pos/7)+.5)*20}%">${a.avatar}</span></div></div><div class="adv-controls"><button class="small" data-active="dir" data-i="-7" ${a.busy?'disabled':''}>⬆️</button><button class="small" data-active="dir" data-i="-1" ${a.busy?'disabled':''}>⬅️</button><button class="small" data-active="dir" data-i="1" ${a.busy?'disabled':''}>➡️</button><button class="small" data-active="dir" data-i="7" ${a.busy?'disabled':''}>⬇️</button></div><div class="adv-bag">🎒 ${a.bag.map(o=>`<b>${o.l}</b>`).join('')}</div>`:chest?`<button class="chest-button reward-pop" data-active="finish">🎁<strong>Otwórz skarb!</strong></button>`:`<div class="word-slots">${[...a.word].map((l,i)=>`<span class="slot ${i<a.assembled.length?'filled':''}">${i<a.assembled.length?l:'·'}</span>`).join('')}</div><div class="letters">${a.bag.map((o,i)=>`<button class="letter" data-active="assemble" data-i="${i}" ${a.assembled.includes(i)?'disabled':''}>${o.l}</button>`).join('')}</div><button class="small" data-active="helpWord">💡 Pomoc Luli</button>`}`;}
 if(a.kind==='rally'){body=`<div class="adv-target"><span>${a.pic}</span><strong>${a.word}</strong><span>${a.letters.join(' ')} ${'· '.repeat(a.word.length-a.letters.length)}</span></div><div class="rally-road">${a.rows.map((row,r)=>`<div class="rally-row">${row.map((cell,i)=>`<button data-active="lane" data-i="${i}" aria-label="Pas ${i+1}" class="road-cell">${cell.letter?`<b class="letter-gem">${cell.letter}</b>`:cell.obstacle||''}</button>`).join('')}</div>`).join('')}<div class="rally-row car-row">${range(0,2).map(i=>`<button data-active="lane" data-i="${i}" class="road-cell ${i===a.lane?'car-active':''}">${i===a.lane?'🏎️':'·'}</button>`).join('')}</div></div><div class="adv-controls"><button class="small" data-active="lane" data-i="${Math.max(0,a.lane-1)}">⬅️</button>${a.letters.length===a.word.length?`<button class="primary" data-active="finish">🏁 Meta!</button>`:`<button class="primary" data-active="drive">${a.running?'⏸ Pauza':'▶ Jedziemy!'}</button>`}<button class="small" data-active="lane" data-i="${Math.min(2,a.lane+1)}">➡️</button></div>`}
 if(a.kind==='pizza'){body=`<div class="adv-target"><span>${a.customer}</span><strong>Zamówienie ${Math.min(a.goal,a.total+1)}/${a.goal}</strong></div><button class="small" data-active="readOrder">🔊 Zamówienie</button><div class="order-strip">${a.order.map(o=>`<div><span>${TOPPINGS[o.i][0]}</span><b>${o.n} × ${TOPPINGS[o.i][1]}</b></div>`).join('')}</div><div class="pizza-base">${a.placed.map((i,j)=>{const ang=j*2.4,rad= j===0?0:Math.min(39,12*Math.sqrt(j));return `<button class="pizza-piece" data-active="removeTop" data-i="${j}" style="left:${50+rad*Math.cos(ang)}%;top:${50+rad*Math.sin(ang)}%" aria-label="Zdejmij ${TOPPINGS[i][1]}">${TOPPINGS[i][0]}</button>`}).join('')}</div><div class="topping-tray">${TOPPINGS.map(([p,n],i)=>`<button class="small" data-active="topping" data-i="${i}"><span>${p}</span>${n}</button>`).join('')}</div><div class="actions"><button class="small" data-active="pizzaClear">🧽 Od nowa</button><button class="primary" data-active="serve">🍽️ Podaj pizzę</button></div>`}
 if(a.kind==='fishing'){body=`<div class="adv-target"><span>🎣</span><strong>${a.catches.length}/${a.goal} skarbów</strong></div><div class="fish-lake"><div class="fish-bank">🪷　🌿　🦆　🌿　🪷</div>${a.fish.map((f,i)=>`<button class="fish-swim ${a.hook===i?'hooked':''}" data-active="catch" data-i="${i}" style="left:${[18,50,82,22,55,82][i]}%;top:${i<3?34:73}%" ${a.busy||a.catches.length===a.goal?'disabled':''} aria-label="Zarzuć wędkę"><span>${f.fish}${a.hook===i?' 🪝':''}</span></button>`).join('')}</div>${a.last?`<div class="adv-target"><span>${a.last.pic}</span><strong>${a.last.word}</strong><button class="small" data-active="listen">🔊</button></div>`:''}<div class="adv-bag">${a.catches.map(f=>`<b>${f.pic} ${f.word}</b>`).join('')}</div>${a.catches.length===a.goal?`<button class="primary" data-active="finish">🎁 Pokaż skarb</button>`:''}`}
 if(a.kind==='freeze'){body=`<div class="freeze-stage ${a.phase==='dance'?'dancing':a.phase==='stop'?'frozen':''}"><div class="freeze-stars">⭐ 🎵 ⭐</div><div class="freeze-lula">${a.phase==='stop'?'🗿':'🐰'}</div><h2>${a.phase==='dance'?'TAŃCZ!':a.phase==='stop'?'STOP!':a.phase==='readyDone'?'BRAWO!':'GOTOWA?'}</h2><p>${a.phase==='dance'?'Muzyka gra!':a.phase==='stop'?'Zostań tak przez chwilkę.':a.phase==='readyDone'?'Jak było?':'Klaśnij, podskocz lub zatańcz po swojemu.'}</p></div><p>${a.round}/${a.goal} rundy · bez kamery, bez oceniania</p><div class="actions">${a.phase==='readyDone'?'<button class="primary" data-active="finish">🎁 Koniec tańca</button>':['dance','stop'].includes(a.phase)?'<button class="small" data-active="freezePause">⏸ Pauza</button>':'<button class="primary" data-active="freezeStart">🎵 Zaczynamy!</button>'}</div>`}
 app.innerHTML=top()+`<section class="panel active-panel"><h1>${g.icon} ${g.name}</h1>${body}<p class="adv-note" role="status">${esc(a.note||'')}</p><div class="actions"><button class="small" data-active="album">🎁 Album skarbów</button><button class="small" data-act="home">🏠 Menu</button></div></section>`;
 if(a.kind==='island'&&a.from!==undefined){const el=$('.island-avatar');if(el){const dx=(a.from%7-a.pos%7)*el.parentElement.clientWidth/7,dy=(Math.floor(a.from/7)-Math.floor(a.pos/7))*el.parentElement.clientHeight/5;el.animate([{transform:`translate(calc(-50% + ${dx}px),calc(-50% + ${dy}px))`},{transform:'translate(-50%,-50%)'}],{duration:150})}delete a.from}
}
function advClick(d){if(d.active==='album'){rewardAlbum();return}if(d.active==='again'||d.active==='long'){advStart(adv.kind,d.active==='long');return}if(screen!=='active'||!adv)return;const a=adv,i=+d.i;switch(d.active){case'walk':islandMove(i);break;case'dir':if((i===-1&&a.pos%7===0)||(i===1&&a.pos%7===6))return;islandMove(a.pos+i);break;case'avatar':a.avatar=d.v;store.pirateAvatar=d.v;save();advRender();break;case'assemble':islandLetter(i);break;case'helpWord':islandLetter(a.bag.findIndex((o,j)=>!a.assembled.includes(j)&&o.l===a.word[a.assembled.length]));break;case'lane':a.lane=i;advRender();break;case'drive':if(a.running){a.running=false;advClear();advRender()}else{a.running=true;rallyTick()}break;case'readOrder':saySequence(a.order.map(o=>String(o.n)+' '+TOPPINGS[o.i][1].toLowerCase()),true);break;case'topping':if(a.placed.length<16){a.placed.push(i);say(TOPPINGS[i][1].toLowerCase());soundNote(440);advRender()}break;case'removeTop':a.placed.splice(i,1);advRender();break;case'pizzaClear':a.placed=[];advRender();break;case'serve':{const ok=range(0,5).every(k=>a.placed.filter(p=>p===k).length===(a.order.find(o=>o.i===k)?.n||0));if(!ok){a.note='Sprawdź zamówienie. Możesz dodać lub zdjąć składniki.';say('Popatrz na zamówienie.');advRender();break}a.total++;a.order.forEach(o=>collectWord(TOPPINGS[o.i][1]));if(a.total===a.goal){advEnd();break}pizzaOrder();a.note='Pyszna pizza! Następny gość już czeka.';say('Świetnie ci poszło!');advRender();break}case'catch':fishCatch(i);break;case'freezeStart':freezeBegin();break;case'freezePause':advClear();stopMusic();stopVoice();a.phase='ready';advRender();break;case'listen':say(a.kind==='fishing'?a.last?.word.toLowerCase():a.word?.toLowerCase(),true);break;case'finish':if(a.phase==='chest'||a.kind==='rally'&&a.letters.length===a.word.length||a.kind==='fishing'&&a.catches.length===a.goal||a.phase==='readyDone')advEnd();break}}
document.addEventListener('visibilitychange',()=>{if(!document.hidden||screen!=='active'||!adv)return;if(adv.kind==='rally'&&adv.running){adv.running=false;advClear();advRender()}if(adv.kind==='freeze'&&['dance','stop'].includes(adv.phase)){advClear();stopMusic();stopVoice();adv.phase='ready';advRender()}});
window.addEventListener('keydown',e=>{if(screen!=='active'||!adv||!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;if(adv.kind==='island'){e.preventDefault();advClick({active:'dir',i:{ArrowLeft:-1,ArrowRight:1,ArrowUp:-7,ArrowDown:7}[e.key]})}else if(adv.kind==='rally'){e.preventDefault();if(e.key==='ArrowLeft'||e.key==='ArrowRight')advClick({active:'lane',i:Math.max(0,Math.min(2,adv.lane+(e.key==='ArrowLeft'?-1:1)))})}});

// Explore, compose and create: short, independent adventures.
const DISCOVERY_GAMES=[
{id:'post',name:'Poczta zwierzaków',icon:'✉️',desc:'Dostarczaj listy do domków',color:'#fee1af',ink:'#694619'},
{id:'robot',name:'Robot na Marsie',icon:'🤖',desc:'Zaprogramuj trasę do liter',color:'#cedbff',ink:'#37467a'},
{id:'build',name:'Budownicza mostów',icon:'🌉',desc:'Dobieraj klocki i buduj most',color:'#c6e9dc',ink:'#245b4b'},
{id:'shadow',name:'Teatr cieni',icon:'🔦',desc:'Odkrywaj tajemnicze sylwetki',color:'#e3d3f8',ink:'#614284'},
{id:'story',name:'Kino małej reżyserki',icon:'🎬',desc:'Układaj obrazkowe historyjki',color:'#f9d0e1',ink:'#84395a'}];
GAMES.unshift(...DISCOVERY_GAMES);
const DISCOVERY_IDS=DISCOVERY_GAMES.map(g=>g.id);
Object.assign(REWARD_SET,{post:[['📮','Skrzynka pocztowa'],['💌','List od Luli'],['🕊️','Gołąb pocztowy']],robot:[['🤖','Mały robot'],['🪐','Planeta'],['🛸','Latający spodek']],build:[['🧱','Złoty klocek'],['🌉','Model mostu'],['🏗️','Dźwig']],shadow:[['🔦','Latarka'],['🎭','Maska teatru'],['🪄','Magiczna różdżka']],story:[['🎞️','Taśma filmowa'],['🎬','Klaps filmowy'],['📽️','Projektor']]});
const POST_WORDS=[['KOT','🐈'],['LIS','🦊'],['LEW','🦁'],['KURA','🐔'],['KOZA','🐐'],['SOWA','🦉'],['RYBA','🐟'],['PUMA','🐆'],['RAK','🦞'],['FOKA','🦭'],['PANDA','🐼'],['WILK','🐺'],['KROWA','🐄']];
const SHADOWS=[['kot','🐈'],['rower','🚲'],['rakieta','🚀'],['auto','🚗'],['klucz','🔑'],['but','👟'],['balon','🎈'],['gitara','🎸'],['ryba','🐟'],['sowa','🦉'],['motyl','🦋'],['dom','🏠'],['samolot','✈️'],['kubek','☕'],['gruszka','🍐'],['banan','🍌'],['grzyb','🍄'],['parasol','☂️'],['latarka','🔦'],['zegar','🕰️']];
const STORIES=[
['Kwiat w ogrodzie',[['🌰','Nasionko'],['🌱','Kiełek'],['🌻','Kwiat']],'Nasionko kiełkuje, a potem wyrasta kwiat.'],
['Pora na herbatę',[['🫖','Czajnik'],['☕','Herbata'],['😊','Smacznego']],'Zaparzamy herbatę, nalewamy do kubka i pijemy.'],
['Budowa domku',[['🧱','Klocki'],['🏗️','Budowa'],['🏠','Dom']],'Najpierw klocki, potem budowa, na końcu domek.'],
['Deszcz i słońce',[['☁️','Chmura'],['🌧️','Deszcz'],['🌈','Tęcza']],'Przychodzi chmura, pada deszcz i pojawia się tęcza.'],
['Urodziny',[['🥣','Miska'],['🎂','Tort'],['🎉','Zabawa']],'Mieszamy ciasto, robimy tort i świętujemy.'],
['Leśna wyprawa',[['🧺','Koszyk'],['🍄','Grzyb'],['🏡','Powrót']],'Bierzemy koszyk, oglądamy grzyby i wracamy do domu.'],
['List dla Luli',[['✏️','Pisanie'],['✉️','List'],['📮','Poczta']],'Piszemy list, wkładamy do koperty i wysyłamy.'],
['Odlot rakiety',[['🧑‍🚀','Astronauta'],['🚀','Start'],['🪐','Planeta']],'Astronauta wsiada do rakiety, startuje i odkrywa planetę.'],
['Spacer z psem',[['🦮','Pies'],['🌳','Park'],['💤','Drzemka']],'Pies idzie do parku, a potem odpoczywa.'],
['Rowerowa przygoda',[['⛑️','Kask'],['🚲','Rower'],['🏁','Meta']],'Zakładamy kask, jedziemy rowerem i docieramy do mety.']];
const DISC_PROMPTS={post:'Posłuchaj, dla kogo jest list. Zanieś go do domku.',robot:'Ułóż strzałki i pomóż robotowi dotrzeć do literki.',build:'Zbuduj most z klocków. Wypełnij wszystkie pola.',shadow:'Znajdź obrazek, który pasuje do cienia.',story:'Ułóż obrazki od początku do końca. Stwórz swój film.'};
let disc=null;
function favList(){return Array.isArray(store.favorites)?store.favorites:[]}
function favorite(id){if(!GAMES.some(g=>g.id===id))return;const list=favList();store.favorites=list.includes(id)?list.filter(x=>x!==id):[...list,id];save();if(screen==='home')home()}
function gameTile(g){const on=favList().includes(g.id);return `<div class="tile-shell" style="--tile:${g.color};--tile-ink:${g.ink}"><button class="tile" data-game="${g.id}" style="--tile:${g.color};--tile-ink:${g.ink}"><span class="emoji">${g.icon}</span><strong>${g.name}</strong><span>${g.desc}</span></button><button class="fav-toggle" data-favorite="${g.id}" aria-pressed="${on}" aria-label="${on?'Usuń z':'Dodaj do'} ulubionych: ${esc(g.name)}">${on?'❤️':'♡'}</button></div>`}
function discStart(kind,extraRound=false){otherScreen('discovery');disc={kind,round:0,note:'',busy:false,word:null,got:[],goal:extraRound?5:3};if(kind==='robot'){[disc.word,disc.pic]=advWord(kind);disc.goal=disc.word.length}discRound();saySequence([DISC_PROMPTS[kind],...(kind==='post'?[disc.target[0].toLowerCase()]:[])])}
function discRound(){const a=disc;a.busy=false;a.note='';a.hint=false;if(a.kind==='post'){let pool=POST_WORDS.filter(w=>!a.got.includes(w[0]));a.target=pick(pool);a.houses=shuffle([a.target,...shuffle(pool.filter(w=>w!==a.target)).slice(0,3)])}
if(a.kind==='robot'){a.pos=20;a.target=pick([2,4,7,9,12,14,1,3]);a.commands=[];a.rocks=shuffle(range(0,24).filter(i=>i!==a.target&&i!==20&&i%5!==0&&Math.floor(i/5)!==Math.floor(a.target/5)&&Math.floor(i/5)!==0)).slice(0,3)}
if(a.kind==='build'){a.length=pick([7,8,9,10,11,12]);a.blocks=[];a.filled=0;a.choices=shuffle([1,2,3,4]);}
if(a.kind==='shadow'){a.target=pick(SHADOWS.filter(w=>!a.got.includes(w[0])));a.choices=shuffle([a.target,...shuffle(SHADOWS.filter(w=>w!==a.target)).slice(0,3)])}
if(a.kind==='story'){a.story=pick(STORIES.filter(w=>!a.got.includes(w[0])));a.cards=shuffle([0,1,2]);a.sequence=[]}discRender()}
function discDone(){const a=disc;if(a.busy)return;a.round++;a.busy=true;a.note='🌟 Udało się!';soundNote(660,0,.18);say(pick(PRAISE));discRender()}
function discEnd(){const a=disc,kind=a.kind;const stat=store.stats[kind]||{done:0,help:0};stat.done++;store.stats[kind]=stat;store.lastGame=kind;const album=awardAlbum(kind);const decor=gift(false);save();otherScreen('discoveryDone');app.innerHTML=top()+`<section class="panel finish"><div class="pic reward-pop">${album?.[0]||'🌟'} 🎉</div><h1>Wielkie odkrycie!</h1><p class="question">${album?'Twój skarb: '+esc(album[1]):'Wspaniała wyprawa!'}</p>${decor?`<p>${decor[0]} Nowa ozdoba: ${esc(decor[1])}</p>`:''}<div class="actions"><button class="primary" data-disc="again">Jeszcze raz ↻</button>${kind!=='robot'?'<button class="small" data-disc="longer">🌟 Dłuższa wyprawa · 5 rund</button>':''}<button class="small" data-favorite="${kind}">${favList().includes(kind)?'❤️':'♡'} Ulubiona gra</button><button class="small" data-active="album">🎁 Album</button><button class="small" data-act="home">🗺️ Inna gra</button></div></section>`;say('Brawo! Odkryłaś kolejny skarb!');updateAtSafePoint();void checkForUpdates()}
function robotStep(pos,dir){const x=pos%5,y=Math.floor(pos/5),nx=x+({L:-1,R:1,U:0,D:0}[dir]||0),ny=y+({L:0,R:0,U:-1,D:1}[dir]||0);if(nx<0||nx>=5||ny<0||ny>=5)return pos;return ny*5+nx}
const ARROWS={U:'↑',D:'↓',L:'←',R:'→'};
function robotRun(){const a=disc;if(a.busy||!a.commands.length)return;const cmds=a.commands.slice();a.commands=[];a.busy=true;a.note='Robot rusza!';discRender();const t=token;let i=0;function step(){if(screen!=='discovery'||disc!==a||t!==token)return;if(i>=cmds.length){a.busy=false;a.note='Możesz dodać następne strzałki.';discRender();return}const p=robotStep(a.pos,cmds[i++]);if(a.rocks.includes(p)||p===a.pos){a.busy=false;a.note='Tu jest przeszkoda. Wybierz inną drogę.';discRender();return}a.pos=p;soundNote(360+i*35,0,.08);if(p===a.target){a.busy=false;const l=a.word[a.round];a.got.push(l);if(a.round+1===a.goal)collectWord(a.word);discDone();say(a.round===a.goal?a.word.toLowerCase():l.toLowerCase());return}discRender();timer=setTimeout(step,280)}timer=setTimeout(step,140)}
function discRender(){if(screen!=='discovery')return;const a=disc,g=DISCOVERY_GAMES.find(g=>g.id===a.kind);let body='',done=a.round>=a.goal,disabled=a.busy?'disabled':'';
if(a.kind==='post'){body=`<div class="post-letter"><span>✉️</span><strong>${a.target[0]}</strong>${a.hint?`<span>${a.target[1]}</span>`:''}<button class="small" data-disc="listen">🔊 Posłuchaj</button></div><div class="post-houses">${a.houses.map(([w,p],i)=>`<button class="post-house" data-disc="house" data-i="${i}" ${disabled}><span>🏡</span><b>${p}</b><strong>${w}</strong></button>`).join('')}</div><button class="small" data-disc="hint" ${disabled}>💡 Pokaż obrazek</button>`}
if(a.kind==='robot'){body=`<div class="robot-goal">${a.pic} ${[...a.word].map((l,i)=>`<span class="letter-chip">${i<a.got.length?l:'·'}</span>`).join('')} <button class="small" data-disc="listen">🔊</button></div><div class="robot-grid">${range(0,24).map(i=>`<div class="robot-cell ${a.rocks.includes(i)?'rock':''} ${a.pos===i?'robot-here':''}" aria-label="${a.pos===i?'Robot':a.target===i?'Litera':a.rocks.includes(i)?'Kamień':'Pole'}">${a.pos===i?'🤖':a.target===i?a.word[Math.min(a.round,a.word.length-1)]:a.rocks.includes(i)?'🪨':'·'}</div>`).join('')}</div><div class="robot-program">${a.commands.map(c=>`<b>${ARROWS[c]}</b>`).join('')||'Ułóż strzałki'}</div><div class="robot-arrows">${Object.entries(ARROWS).map(([d,ico])=>`<button class="answer" data-disc="command" data-v="${d}" ${disabled}>${ico}</button>`).join('')}</div><div class="actions"><button class="primary" data-disc="run" ${disabled||(!a.commands.length?'disabled':'')}>▶ Jedź</button><button class="small" data-disc="undo" ${disabled}>↶ Cofnij</button><button class="small" data-disc="resetRobot" ${disabled}>🔄 Od początku</button></div>`}
if(a.kind==='build'){body=`<div class="bridge-count">🌉 ${a.filled} / ${a.length} <small>pól</small></div><div class="build-river"><span class="bridge-bank">🦊</span><div class="build-span" style="--n:${a.length}">${range(0,a.length-1).map(i=>`<span class="${i<a.filled?'placed':''}" style="--brick:${a.blocks.findIndex((_,j)=>a.blocks.slice(0,j+1).reduce((n,k)=>n+k,0)>i)%4}">${i<a.filled?'':'·'}</span>`).join('')}</div><span class="bridge-bank">🏡</span></div><p>Dobierz klocki i wypełnij lukę.</p><div class="block-options">${a.choices.map(n=>`<button class="build-block" data-disc="block" data-i="${n}" ${disabled}><strong>${n}</strong><span>${'🟫'.repeat(n)}</span></button>`).join('')}</div><div class="actions"><button class="small" data-disc="undoBlock" ${disabled}>↶ Cofnij klocek</button></div>`}
if(a.kind==='shadow'){body=`<div class="shadow-stage"><span class="shadow-shape ${a.hint||a.busy?'revealed':''}">${a.target[1]}</span></div><div class="shadow-options">${a.choices.map(([w,p],i)=>`<button class="answer" data-disc="shadow" data-i="${i}" ${disabled}>${p}</button>`).join('')}</div><button class="small" data-disc="hint" ${disabled}>🔦 Zapal światło</button>`}
if(a.kind==='story'){body=`<h3>${esc(a.story[0])}</h3><div class="story-film">${range(0,2).map((_,i)=>`<div class="film-frame"><small>${i+1}</small><span>${a.sequence.length>i?a.story[1][a.sequence[i]][0]:'?'}</span></div>`).join('')}</div><div class="story-cards">${a.cards.map(i=>`<button class="story-card" data-disc="frame" data-i="${i}" ${disabled||a.sequence.includes(i)?'disabled':''}><span>${a.story[1][i][0]}</span><strong>${esc(a.story[1][i][1])}</strong></button>`).join('')}</div><div class="actions"><button class="small" data-disc="storyUndo" ${disabled}>↶ Cofnij</button><button class="small" data-disc="storyListen">🔊 Posłuchaj historii</button></div>`}
app.innerHTML=top()+`<section class="panel discovery-panel"><div class="gamehead"><h2>${g.icon} ${g.name}</h2><strong>${a.round} / ${a.goal}</strong></div><div class="progress">${range(0,a.goal-1).map(i=>`<span class="${i<a.round?'past':i===a.round?'now':''}"></span>`).join('')}</div>${body}<p class="feedback" role="status">${esc(a.note||' ')}</p>${a.busy&&a.note.startsWith('🌟')?`<button class="primary" data-disc="next">${done?'Odbierz skarb 🎁':'Dalej ➜'}</button>`:''}</section>`}
function discClick(d){if(d.disc==='again'||d.disc==='longer'){discStart(disc.kind,d.disc==='longer');return}if(screen!=='discovery'||!disc)return;const a=disc,i=+d.i;if(d.disc==='next'&&a.busy&&a.note.startsWith('🌟')){if(a.round===a.goal)discEnd();else{discRound();if(a.kind==='post')say(a.target[0].toLowerCase())}return}if(d.disc==='listen'){say(a.kind==='post'?a.target[0].toLowerCase():a.word.toLowerCase(),true);return}if(d.disc==='storyListen'){say(a.story[2],true);return}if(a.busy)return;switch(d.disc){case'house':if(a.houses[i]===a.target){a.got.push(a.target[0]);collectWord(a.target[0]);discDone();say(a.target[0].toLowerCase());return}a.note='To inny domek. Spróbuj jeszcze raz!';break;case'hint':a.hint=true;if(a.kind==='post')say(a.target[0].toLowerCase(),true);break;case'command':if(a.commands.length<10&&ARROWS[d.v])a.commands.push(d.v);break;case'undo':a.commands.pop();break;case'resetRobot':a.pos=20;a.commands=[];break;case'run':robotRun();return;case'block':if(a.filled+i<=a.length){a.blocks.push(i);a.filled+=i;soundNote(330+i*70);if(a.filled===a.length){discDone();return}}else a.note='Ten klocek jest za długi. Wybierz krótszy.';break;case'undoBlock':if(a.blocks.length)a.filled-=a.blocks.pop();break;case'shadow':if(a.choices[i]===a.target){a.got.push(a.target[0]);discDone();say(a.target[0]);return}a.note='Spójrz na kształt jeszcze raz.';break;case'frame':if(a.sequence.includes(i))return;if(i!==a.sequence.length){a.note='Co wydarzyło się wcześniej? Możesz posłuchać historii.';break}a.sequence.push(i);say(a.story[1][i][1].toLowerCase());if(a.sequence.length===3){a.got.push(a.story[0]);discDone();say(a.story[2]);return}break;case'storyUndo':a.sequence.pop();break;}discRender()}

