function jumpBook(){if(!store.platform||typeof store.platform!=='object')store.platform={unlocked:0,done:[],lastWords:{}};return store.platform}
function jumpStop(){if(jumpFrame)cancelAnimationFrame(jumpFrame);jumpFrame=0;jumpKeys.clear();jumpPointers.clear();jumpLast=0}
function jumpMenu(){otherScreen('platformMenu');const book=jumpBook();app.innerHTML=top()+`<section class="panel jump-menu"><div class="jump-title"><span>🐰</span><div><h1>Skoki Luli</h1><p>Odszukaj litery i otwórz magiczne portale!</p></div></div><div class="jump-worlds">${JUMP_WORLDS.map((w,i)=>`<button class="jump-world" data-jump="world" data-i="${i}" style="--sky:${w.sky};--hill:${w.hills}" ${i>book.unlocked?'disabled':''}><span>${w.icon}</span><strong>${w.name}</strong><span>${i>book.unlocked?'🔒 Odkryj wcześniejszą krainę':book.done.includes(i)?'⭐ Odkryta · zagraj ponownie':'👣 Wyrusz!'}</span></button>`).join('')}</div><p class="sub">Skacz, kiedy chcesz. Nie ma przepaści, życia ani limitu czasu.</p><div class="actions"><button class="small" data-jump="world" data-i="0">▶ Zagraj od początku</button><button class="small" data-act="home">🏠 Inne gry</button></div></section>`;updateAtSafePoint()}
function jumpStart(i){if(!Number.isInteger(i)||i<0||i>=JUMP_WORLDS.length||i>jumpBook().unlocked)return;otherScreen('platformPlay');const w=JUMP_WORLDS[i],book=jumpBook(),[word,pic]=pick(w.words.filter(x=>x[0]!==book.lastWords[i]));book.lastWords[i]=word;save();const base=365,step=310,letters=[...word].map((l,k)=>{const lifted=i>0&&(k+i)%2===1;const x=275+k*step+Math.floor(Math.random()*61)-30;return{l,x,y:base-(lifted?w.height:0)-37,got:false,lifted}});const platforms=letters.filter(l=>l.lifted).map(l=>({x:l.x-90,y:base-w.height,w:180}));jumper={i,w,word,pic,letters,platforms,length:letters.at(-1).x+350,x:90,y:base-44,vy:0,ground:true,cam:0,dir:1,auto:null,jumpHeld:false,finished:false,notice:'Znajdź literki!',base,elapsed:0};app.innerHTML=top()+`<section class="panel jump-panel"><div class="jump-hud"><div><h2>${w.icon} ${w.name}</h2><span>Etap ${i+1} z ${JUMP_WORLDS.length}</span></div><div class="jump-target"><span>${pic}</span><div id="jumpSlots" class="jump-slots"></div><button class="small jump-listen" data-jump="listen" aria-label="Posłuchaj słowa">🔊</button></div></div><canvas id="jumpCanvas" width="920" height="420" aria-label="Platformówka: Lula na drodze z literami"></canvas><div id="jumpNote" class="jump-note" role="status"></div><div class="jump-controls"><div><button class="jump-key" data-jump-hold="left" aria-label="Idź w lewo">⬅</button><button class="jump-key" data-jump-hold="right" aria-label="Idź w prawo">➡</button></div><button class="jump-key jump-up" data-jump-hold="up" aria-label="Skocz">⬆ Skok</button></div><div class="actions"><button class="small" data-jump="assist">💡 Prowadź mnie</button><button class="small" data-jump="menu">🗺️ Krainy</button></div><p class="sub">Przytrzymaj strzałkę, żeby iść. Skacz lub dotknij miejsca na planszy. Na klawiaturze: ← → i spacja.</p></section>`;jumpHUD();jumpBind();saySequence(['Skacz i zbieraj literki. Otwórz magiczny portal.',word.toLowerCase()]);jumpFrame=requestAnimationFrame(jumpTick)}
function jumpHUD(){const a=jumper;if(!a)return;const slots=$('#jumpSlots'),note=$('#jumpNote');if(slots)slots.innerHTML=a.letters.map(o=>`<span class="${o.got?'found':''}">${o.got?o.l:'·'}</span>`).join('');if(note){const n=a.letters.filter(o=>o.got).length;note.textContent=`${a.notice} · ${n}/${a.letters.length} liter`}}
function jumpBind(){const canvas=$('#jumpCanvas');canvas.onpointerdown=e=>{if(screen!=='platformPlay')return;const r=canvas.getBoundingClientRect();jumper.auto=Math.max(30,Math.min(jumper.length-25,jumper.cam+(e.clientX-r.left)*920/r.width));if((e.clientY-r.top)*420/r.height<jumper.y)jumpKeys.add('once')};app.querySelectorAll('[data-jump-hold]').forEach(b=>{b.onpointerdown=e=>{if(screen!=='platformPlay')return;e.preventDefault();b.setPointerCapture(e.pointerId);jumpPointers.set(e.pointerId,b.dataset.jumpHold);jumper.auto=null};const release=e=>jumpPointers.delete(e.pointerId);b.onpointerup=release;b.onpointercancel=release;b.onlostpointercapture=release})}
window.addEventListener('keydown',e=>{if(screen!=='platformPlay')return;const key={ArrowLeft:'left',ArrowRight:'right',ArrowUp:'up',' ':'up'}[e.key];if(key){e.preventDefault();if(!e.repeat){jumpKeys.add(key);jumper.auto=null}}});window.addEventListener('keyup',e=>{const key={ArrowLeft:'left',ArrowRight:'right',ArrowUp:'up',' ':'up'}[e.key];if(key)jumpKeys.delete(key)});window.addEventListener('blur',()=>{jumpKeys.clear();jumpPointers.clear();if(jumper)jumper.auto=null});
function jumpTick(ms){if(screen!=='platformPlay'||!jumper||jumper.finished){jumpStop();return}const a=jumper,dt=Math.min(.035,jumpLast?(ms-jumpLast)/1000:0);jumpLast=ms;a.elapsed+=dt;const down=k=>jumpKeys.has(k)||[...jumpPointers.values()].includes(k);let dir=Number(down('right'))-Number(down('left'));if(a.auto!==null&&!dir){const dx=a.auto-a.x;if(Math.abs(dx)<9)a.auto=null;else dir=Math.sign(dx)}if(dir)a.dir=dir;const oldBottom=a.y+44;let jump=down('up')||jumpKeys.has('once');jumpKeys.delete('once');const near=a.letters.find(l=>!l.got&&l.lifted&&Math.abs(l.x-a.x)<70);if(a.auto!==null&&near&&a.ground&&a.y+44>near.y+28)jump=true;if(jump&&a.ground&&!a.jumpHeld){a.vy=-520;a.ground=false;soundNote(420,0,.10)}a.jumpHeld=jump;a.x=Math.max(25,Math.min(a.length-25,a.x+dir*235*dt));a.vy+=1160*dt;a.y+=a.vy*dt;a.ground=false;const surfaces=[{x:0,w:a.length,y:a.base},...a.platforms];const landing=surfaces.filter(p=>a.x+15>p.x&&a.x-15<p.x+p.w&&oldBottom<=p.y+1&&a.y+44>=p.y&&a.vy>=0).sort((p,q)=>p.y-q.y)[0];if(landing){a.y=landing.y-44;a.vy=0;a.ground=true}if(a.y+44>a.base){a.y=a.base-44;a.vy=0;a.ground=true}for(const l of a.letters){if(!l.got&&Math.abs(a.x-l.x)<40&&Math.abs(a.y+22-l.y)<42){l.got=true;soundNote(660,0,.15);a.notice='Znaleziono '+l.l+'!';if(a.letters.every(o=>o.got)){a.notice='Komplet! Idź do tęczowego portalu.';saySequence([a.word.toLowerCase(),'Brawo!']);a.auto=null}jumpHUD()}}a.cam=Math.max(0,Math.min(a.length-920,a.x-310));if(a.x>a.length-105&&a.letters.every(l=>l.got)){jumpComplete();return}if(a.x>a.length-105&&!a.letters.every(l=>l.got)&&a.notice!=='Portal czeka na pozostałe literki.'){a.notice='Portal czeka na pozostałe literki.';jumpHUD()}jumpDraw();jumpFrame=requestAnimationFrame(jumpTick)}
function jumpDraw(){const a=jumper,c=$('#jumpCanvas');if(!a||!c)return;const ctx=c.getContext('2d'),W=920,H=420,cam=a.cam,w=a.w;const rect=(x,y,ww,h,col)=>{ctx.fillStyle=col;ctx.fillRect(x,y,ww,h)};const ellipse=(x,y,rx,ry,col)=>{ctx.fillStyle=col;ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);ctx.fill()};const text=(s,x,y,size,color='#263c42')=>{ctx.fillStyle=color;ctx.font=`bold ${size}px system-ui, sans-serif`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(s,x,y)};const grad=ctx.createLinearGradient(0,0,0,H);grad.addColorStop(0,w.sky);grad.addColorStop(1,'#fff6dc');rect(0,0,W,H,grad);ellipse(760,72,43,43,'#fff5b0');for(let k=0;k<7;k++){let x=((k*219+130-cam*.18)%1400+1400)%1400-150;ellipse(x,82+(k%3)*24,65,18,'#ffffffbb');ellipse(x-22,69+(k%3)*24,27,28,'#ffffffcc');ellipse(x+18,67+(k%3)*24,35,31,'#ffffffcc')}for(let k=0;k<8;k++){let x=((k*275-cam*.35)%2200+2200)%2200-210;ellipse(x,349,200,135+(k%3)*20,w.hills)}rect(0,a.base,W,H-a.base,w.soil);rect(0,a.base,W,15,w.ground);for(let k=0;k<Math.ceil(a.length/82);k++){const x=k*82-cam;if(x< -80||x>W+80)continue;ellipse(x+20,a.base+34,4,3,'#ffffff55');if(k%4===0)text(a.i===2?'💎':a.i===1?'🍄':a.i===3?'🌸':'🌼',x+18,a.base-13,26);if(k%7===2){rect(x+6,260,12,105,'#a87b59');ellipse(x+12,254,39,47,a.i===2?'#bba1f2':'#7eba90');ellipse(x-8,232,28,31,a.i===2?'#cfc1f9':'#95cba1')}}for(const p of a.platforms){const x=p.x-cam;rect(x,p.y,p.w,20,'#866b59');rect(x,p.y,p.w,7,w.ground);for(let k=10;k<p.w;k+=25)ellipse(x+k,p.y+12,4,2,'#ffffff66')}for(const l of a.letters){if(l.got)continue;const x=l.x-cam,y=l.y+Math.sin(a.elapsed*3+l.x)*4;ellipse(x,y,25,25,'#dba64a');ellipse(x,y-2,22,22,'#ffeba0');ellipse(x-7,y-8,5,5,'#fff9d6');text(l.l,x,y+1,28,'#6d471a')}const gate=a.length-65-cam,ready=a.letters.every(l=>l.got);rect(gate-33,242,66,123,ready?'#8470c9':'#8d94a1');ellipse(gate,244,33,31,ready?'#8470c9':'#8d94a1');rect(gate-24,252,48,113,ready?'#c9ecff':'#c3cbd4');ellipse(gate,251,24,24,ready?'#c9ecff':'#c3cbd4');text(ready?'🌟':'🔒',gate,302,34);text('META',gate,220,16,'#42396d');const x=a.x-cam,y=a.y;ellipse(x,a.base+2,20,5,'#38504a33');const moving=jumpKeys.has('left')||jumpKeys.has('right')||jumpPointers.size||a.auto!==null;const bob=moving&&a.ground?Math.sin(a.elapsed*18)*2:0;ctx.save();ctx.translate(x,y+bob);ellipse(-9,-6,6,17,'#fff5ed');ellipse(9,-6,6,17,'#fff5ed');ellipse(-9,-7,3,11,'#e9a2bb');ellipse(9,-7,3,11,'#e9a2bb');ellipse(0,24,17,18,'#9e80cf');ellipse(0,8,17,16,'#fff5ed');ellipse(-6,6,2.5,3,'#47374c');ellipse(6,6,2.5,3,'#47374c');ellipse(a.dir*3,13,3,2,'#d88ca5');ellipse(-10,40,8,4,'#fff5ed');ellipse(10,40,8,4,'#fff5ed');ctx.restore();if(a.auto!==null){const xx=a.auto-cam;if(xx>0&&xx<W){ctx.strokeStyle='#ffffffaa';ctx.lineWidth=3;ctx.beginPath();ctx.arc(xx,350,12,0,Math.PI*2);ctx.stroke()}}}
function jumpComplete(){const a=jumper;if(!a||a.finished)return;a.finished=true;jumpStop();const b=jumpBook();if(!b.done.includes(a.i))b.done.push(a.i);b.unlocked=Math.max(b.unlocked,Math.min(JUMP_WORLDS.length-1,a.i+1));collectWord(a.word);const s=store.stats.platform||{done:0,help:0};s.done++;store.stats.platform=s;store.lastGame='platform';const prize=awardAlbum('platform'),decor=gift(false);save();otherScreen('platformDone');app.innerHTML=top()+`<section class="panel finish jump-finish"><div class="pic reward-pop">${prize?.[0]||'🌟'} 🎉</div><h1>Portal otwarty!</h1><div class="big">${a.pic} ${a.word}</div><p>${prize?'Nowy skarb: '+esc(prize[1]):'Kolejne słowo w kolekcji!'}${decor?' · '+esc(decor[1]):''}</p><div class="actions">${a.i<JUMP_WORLDS.length-1?`<button class="primary" data-jump="world" data-i="${a.i+1}">🌈 Następna kraina</button>`:'<button class="primary" data-jump="menu">🗺️ Wszystkie krainy</button>'}<button class="small" data-jump="world" data-i="${a.i}">↻ Nowe słowo</button><button class="small" data-active="album">🎁 Album skarbów</button><button class="small" data-act="home">🏠 Inna gra</button></div></section>`;saySequence([a.word.toLowerCase(),'Brawo! Odkryłaś kolejny skarb!']);updateAtSafePoint();void checkForUpdates()}
function jumpClick(d){if(d.jump==='menu'){jumpMenu();return}if(d.jump==='world'){jumpStart(+d.i);return}if(screen!=='platformPlay')return;if(d.jump==='listen')say(jumper.word.toLowerCase(),true);if(d.jump==='assist'){const a=jumper,l=a.letters.find(x=>!x.got);a.auto=l?l.x:a.length-65;a.notice=l?'Lula pokaże drogę do literki.':'Lula prowadzi do portalu.';if(l?.lifted) a.auto=l.x+20;jumpHUD()}}

// v2.2 — writing adventures, keyboard and parent-assisted paper mode.
const WRITE_GAME={id:'writing',name:'Magiczna poczta słów',icon:'✉️',desc:'Pisz na kartce: z wzoru lub ze słuchu',color:'#fce6bd',ink:'#68410f'};
GAMES.unshift(WRITE_GAME);
REWARD_SET.writing=[['✉️','Złota koperta'],['🪶','Magiczne pióro'],['📮','Czerwona skrzynka'],['🦉','Sowa listonoszka'],['📖','Księga słów'],['🚀','Kosmiczna poczta']];
const WRITE_CHAPTERS=[
 {name:'Leśna poczta',icon:'🦊',bg:'#e4f4d4',scene:'🌲 🏡 🌳',story:'Lisek roznosi listy po lesie. Podpisz koperty, a otworzy się droga do kolejnego domku.',words:[['KOT','🐈'],['LAS','🌲'],['LIS','🦊'],['LEW','🦁'],['DOM','🏠'],['RAK','🦞'],['SOWA','🦉'],['RYBA','🐟'],['KURA','🐔'],['KOZA','🐐'],['PANDA','🐼'],['MOTYL','🦋']]},
 {name:'Piracki list',icon:'🏴‍☠️',bg:'#d9f0fd',scene:'🌴 ⛵ 🐚',story:'Papuga znalazła butelki z listami. Zapisz słowa, aby odkryć ich tajemnicę.',words:[['MAPA','🗺️'],['WODA','💧'],['OKO','👁️'],['NOS','👃'],['BUT','👟'],['SOK','🧃'],['SER','🧀'],['LATO','☀️'],['FOKA','🦭'],['MANGO','🥭'],['BALON','🎈'],['BANAN','🍌']]},
 {name:'Miasteczko Luli',icon:'🐰',bg:'#fce4ef',scene:'🏠 🚗 🏪',story:'Lula potrzebuje szyldów i podpisów w swoim miasteczku. Pomóż jej je napisać.',words:[['AUTO','🚗'],['MAMA','👩'],['TATA','👨'],['LALA','🪆'],['LODY','🍦'],['TORT','🎂'],['LUPA','🔎'],['LAMPA','💡'],['ROWER','🚲'],['KUBEK','☕'],['MELON','🍈'],['TULIPAN','🌷']]},
 {name:'Kosmiczna poczta',icon:'🚀',bg:'#e4dffd',scene:'🪐 🚀 ⭐',story:'Mały robot wysyła wiadomości na planetę Luli. Pomóż mu zapisać tajne kosmiczne słowa.',words:[['LOT','✈️'],['MAK','🌺'],['RAMA','🖼️'],['TOR','🛤️'],['NUTA','🎵'],['FALA','🌊'],['FARBA','🎨'],['LINA','🪢'],['ROBOT','🤖'],['KOMETA','☄️'],['PLANETA','🪐'],['RAKIETA','🚀']]}
];
// Only familiar, unambiguous short spellings in the default pool. No Polish diacritics or digraphs.
let writing=null;
function writingBook(){if(!store.writing||typeof store.writing!=='object')store.writing={mode:'copy',length:'short',recent:[],chapters:{}};if(store.writing.mode==='paper')store.writing.mode='listen';return store.writing}
function writingMenu(){otherScreen('writingMenu');const b=writingBook();app.innerHTML=top()+`<section class="panel write-panel"><div class="write-banner"><span>✉️ 🐰</span><div><h1>Magiczna poczta słów</h1><p>Każde napisane słowo otwiera nową kopertę!</p></div></div><h2 class="write-heading">Jak chcesz pisać?</h2><div class="write-modes">${[['copy','👀','Z wzoru na kartce','Popatrz i napisz na papierze'],['listen','👂','Ze słuchu na kartce','Posłuchaj i napisz na papierze']].map(([id,ico,n,desc])=>`<button class="write-mode ${b.mode===id?'chosen':''}" data-write="mode" data-v="${id}" aria-pressed="${b.mode===id}"><span>${ico}</span><strong>${n}</strong><small>${desc}</small></button>`).join('')}</div><div class="write-settings"><span>Wybierz długość:</span><button class="small ${b.length==='short'?'chosen':''}" data-write="length" data-v="short" aria-pressed="${b.length==='short'}">3–5 liter</button><button class="small ${b.length==='long'?'chosen':''}" data-write="length" data-v="long" aria-pressed="${b.length==='long'}">Także dłuższe</button></div><button class="primary" data-write="chapter" data-i="4">🎲 Losowe słowa ze wszystkich krain</button><h2 class="write-heading">Dokąd wysyłamy listy?</h2><div class="write-chapters">${WRITE_CHAPTERS.map((c,i)=>`<button class="write-chapter" style="--chapter:${c.bg}" data-write="chapter" data-i="${i}"><span>${c.scene}</span><strong>${c.icon} ${c.name}</strong><small>${b.chapters[i]?'⭐ Wyprawy: '+b.chapters[i]:'Otwórz 5 kopert'}</small></button>`).join('')}</div><p class="sub">Bez stopera i ocen. Możesz poprosić Lulę o pomoc lub wybrać inne słowo.</p></section>`;updateAtSafePoint()}
function writingStart(i){if(!WRITE_CHAPTERS[i]&&i!==4)return;otherScreen('writingPlay');const b=writingBook(),c=i===4?{words:WRITE_CHAPTERS.flatMap(x=>x.words)}:WRITE_CHAPTERS[i],pool=c.words.filter(([w])=>b.length==='long'||w.length<=5);let fresh=shuffle(pool.filter(([w])=>!b.recent.includes(w)));const rest=shuffle(pool.filter(([w])=>!fresh.some(([a])=>a===w)));const words=fresh.concat(rest).slice(0,5);writing={i,words,index:0,answers:[],skips:0,mode:b.mode,ended:false};b.recent=[...b.recent,...words.map(([w])=>w)].slice(-32);save();writingNextWord();}
function writingNextWord(){const a=writing;if(!a||a.ended)return;if(a.index>=a.words.length){writingFinish();return}stopVoice();const [word,pic]=a.words[a.index];Object.assign(a,{word,pic,shown:a.mode==='copy',assisted:false});writingRender();}
function writingRender(){const a=writing;app.innerHTML=top()+`<section class="panel write-panel paper-only"><div class="write-title"><h1>✏️ Pisanie na kartce</h1><strong>${a.index+1}/${a.words.length}</strong></div><p>${a.mode==='copy'?'Popatrz na wyraz i napisz go na kartce.':'Posłuchaj wyrazu i napisz go na kartce.'}</p><div class="paper-word">${a.shown?esc(a.word):'👂'}</div><div class="paper-buttons"><button class="primary paper-say" data-write="listen">🔊 Powiedz</button><button class="primary paper-next" data-write="next">Następne słowo ➜</button></div><div class="actions">${a.mode==='listen'?`<button class="small" data-write="model">${a.shown?'🙈 Ukryj wzór':'👀 Pokaż wzór'}</button>`:''}<button class="small" data-write="skip">Inne słowo</button><button class="small" data-write="menu">🗺️ Przygody</button></div><p class="sub">Nie musisz nic wpisywać na ekranie. Powiedz powtarza zawsze ten sam wyraz. Następne słowo zmienia wyraz.</p></section>`}
function writingClick(d){if(d.write==='menu'){writingMenu();return}if(d.write==='mode'){if(['copy','listen'].includes(d.v)){writingBook().mode=d.v;save();writingMenu()}return}if(d.write==='length'){if(['short','long'].includes(d.v)){writingBook().length=d.v;save();writingMenu()}return}if(d.write==='chapter'){writingStart(+d.i);return}if(screen!=='writingPlay'||!writing)return;const a=writing;if(d.write==='listen'){say(a.word.toLowerCase(),true);return}if(d.write==='model'){a.shown=!a.shown;a.assisted=true;writingRender();return}if(d.write==='next'){a.answers.push({index:a.index,word:a.word,assisted:a.assisted,mode:a.mode});collectWord(a.word);a.index++;writingNextWord()}else if(d.write==='skip'){a.skips++;a.index++;writingNextWord()}}
function writingFinish(){const a=writing;if(a.ended)return;a.ended=true;const b=writingBook();let prize=null,decor=null;if(a.answers.length){b.chapters[a.i]=(b.chapters[a.i]||0)+1;const stat=store.stats.writing||{done:0,help:0};stat.done+=a.answers.length;stat.help+=a.answers.filter(x=>x.assisted).length;store.stats.writing=stat;store.lastGame='writing';prize=awardAlbum('writing');decor=gift(false);save()}otherScreen('writingDone');app.innerHTML=top()+`<section class="panel finish write-panel"><div class="pic reward-pop">${prize?.[0]||'💌'} ${a.answers.length?'🎉':''}</div><h1>${a.answers.length?'Wyprawa z kartką zakończona!':'Koniec wyprawy'}</h1><p>${a.answers.length?'Słowa z tej wyprawy:':'Możesz wybrać inną przygodę.'}</p><div class="write-treasures">${a.answers.map(x=>`<button class="small" data-prize="${esc(x.word)}">🔊 ${esc(x.word)}</button>`).join('')}</div>${prize?`<p>Nowy skarb: ${esc(prize[1])}</p>`:''}${decor?`<p>Ozdoba do domku: ${decor[0]} ${esc(decor[1])}</p>`:''}<div class="actions"><button class="primary" data-write="chapter" data-i="${a.i===4?4:(a.i+1)%WRITE_CHAPTERS.length}">Następna przygoda ➜</button><button class="small" data-write="chapter" data-i="${a.i}">↻ Inne słowa</button><button class="small" data-write="menu">✉️ Wybierz przygodę</button><button class="small" data-active="album">🎁 Album</button><button class="small" data-act="home">🏠 Inna gra</button></div></section>`;if(a.answers.length)say('Brawo! Odkryłaś kolejny skarb!');updateAtSafePoint();void checkForUpdates()}

// Four new adventure campaigns with three independent, replayable levels.
const EXPEDITIONS=[
 {id:'mine',name:'Kopalnia literek',icon:'⛏️',desc:'Kop tunele, rozbijaj skały, szukaj liter',color:'#ead7b6',ink:'#694c2a',levels:['Tunel górnika','Kryształowa żyła','Złota komnata'],story:'Rozbijaj skały przy wolnym tunelu. Odszukaj literki i otwórz kufer!',words:['KOT','LAS','DOM','SOK','MAK','LIS','MAPA','KURA','SOWA','RYBA','LAMPA','BALON','MOTYL','BANAN']},
 {id:'rail',name:'Maszynistka',icon:'🚂',desc:'Prowadź pociąg i przewoź pasażerów',color:'#d2e9cf',ink:'#315838',levels:['Leśna kolej','Kolej nad morzem','Ekspres górski'],story:'Zabierz pasażerów do pociągu. Ustaw zwrotnicę do właściwej stacji i ruszaj!',words:['LAS','DOM','SOK','KOT','MAPA','LATO','SOWA','PANDA','BALON','MOTYL','LAMPA','BANAN']},
 {id:'submarine',name:'Podwodny świat',icon:'🤿',desc:'Steruj łodzią i odkrywaj zatopione skarby',color:'#c6e8f5',ink:'#21566e',levels:['Zatoka muszelek','Rafa koralowa','Zatopiony statek'],story:'Płyń łodzią podwodną do błyszczących skarbów. Zbierz litery i odkryj hasło!',words:['RAK','NOS','OKO','WODA','FALA','RYBA','FOKA','LINA','MAPA','BALON','LAMPA','MOTYL']},
 {id:'potion',name:'Fabryka eliksirów',icon:'🧪',desc:'Mieszaj kolory, licz krople i twórz mikstury',color:'#e6d6f7',ink:'#59417b',levels:['Kolorowe krople','Tęczowe mikstury','Laboratorium Luli'],story:'Dodaj składniki według obrazkowego przepisu. Zmieszaj kolory i zobacz, co powstanie!',words:['MAK','SOK','LATO','FARBA','NUTA','FALA','LILA','LAMPA']}
];
GAMES.unshift(...EXPEDITIONS);
for(const [id,rewards] of Object.entries({mine:[['⛏️','Kilof odkrywczyni'],['💎','Kryształ kopalni'],['🪙','Medal górnika']],rail:[['🚂','Lokomotywa'],['🎫','Złoty bilet'],['🚉','Model dworca']],submarine:[['🐚','Muszla z zatoki'],['🪸','Koral z rafy'],['🤿','Łódź odkrywców']],potion:[['🧪','Kolorowa fiolka'],['🌈','Tęczowy eliksir'],['🔮','Kula magiczna']]}))REWARD_SET[id]=rewards;
let expedition=null;
function expBook(){if(!store.expeditions||typeof store.expeditions!=='object')store.expeditions={};return store.expeditions}
function expProgress(id){const b=expBook();return b[id]||(b[id]={unlocked:0,done:[],last:''})}
function expMenu(id){const g=EXPEDITIONS.find(x=>x.id===id);if(!g)return;otherScreen('expMenu');const b=expProgress(id);app.innerHTML=top()+`<section class="panel exp-panel"><div class="exp-banner" style="--exp:${g.color}"><span>${g.icon}</span><div><h1>${g.name}</h1><p>${g.story}</p></div></div><div class="exp-levels">${g.levels.map((l,i)=>`<button class="exp-level" data-exp="start" data-id="${id}" data-i="${i}" ${i>b.unlocked?'disabled':''}><span>${i>b.unlocked?'🔒':b.done.includes(i)?'⭐':g.icon}</span><strong>${i+1}. ${l}</strong><small>${i>b.unlocked?'Odkryj poprzedni etap':b.done.includes(i)?'Zagraj ponownie':'Wyrusz!'}</small></button>`).join('')}</div><p>Bez pośpiechu. Każdy etap można powtórzyć.</p><button class="small" data-act="home">🏠 Inne gry</button></section>`;updateAtSafePoint()}
function expStart(id,i){const g=EXPEDITIONS.find(x=>x.id===id);if(!g||!Number.isInteger(i)||i<0||i>2||i>expProgress(id).unlocked)return;otherScreen('expPlay');const b=expProgress(id),pool=g.words.filter(w=>i===0?w.length<=3:i===1?w.length<=4:true),valid=pool.filter(w=>w!==b.last),word=pick(valid.length?valid:pool);b.last=word;save();expedition={id,i,g,word,pic:PICTURE_WORDS.find(([w])=>w===word)?.[1]||'🎁',found:[],note:'',stage:'play',round:0,done:false};const a=expedition;
 if(id==='mine'){a.cols=6;a.rows=4;a.open=[18];const loc=shuffle(range(0,23).filter(n=>n!==18)).slice(0,word.length);a.cells={};loc.forEach((p,j)=>a.cells[p]={letter:word[j],index:j});a.hits={};a.hard=shuffle(range(0,23).filter(n=>n!==18)).slice(0,2+i*3);a.note='Dotykaj skał obok odkrytego tunelu.'}
 if(id==='submarine'){a.cols=6;a.rows=4;a.pos=18;a.cells={};shuffle(range(0,23).filter(n=>n!==18)).slice(0,word.length).forEach((p,j)=>a.cells[p]={letter:word[j],index:j});a.rocks=shuffle(range(0,23).filter(n=>n!==18&&!a.cells[n])).slice(0,2+i);a.note='Dotknij pola obok łodzi lub użyj strzałek.'}
 if(id==='rail'){a.goal=2+i;expRailRound()}
 if(id==='potion'){a.goal=2+i;expPotionRound()}
 expRender();say(g.story)}
const EXP_COLORS=[['🔴','Czerwony','#df5959'],['🔵','Niebieski','#4d8ce0'],['🟡','Żółty','#f0c747']];
const EXP_MIX=[{c:[0,1],name:'Fioletowy',color:'#9965c9'},{c:[0,2],name:'Pomarańczowy',color:'#ef923b'},{c:[1,2],name:'Zielony',color:'#66b86b'}];
function expPotionRound(){const a=expedition,m=pick(EXP_MIX);a.recipe=[0,0,0];m.c.forEach(k=>a.recipe[k]=1+Math.floor(Math.random()*(2+a.i)));a.mix=m;a.drops=[0,0,0];a.note='Dodaj krople według przepisu.'}
function expRailRound(){const a=expedition,pool=[['LAS','🌲'],['DOM','🏠'],['KOT','🐈'],['SOWA','🦉'],['MAPA','🗺️'],['LATO','☀️'],['PANDA','🐼'],['BALON','🎈']].filter(([w])=>a.i===0?w.length<=3:true);a.stations=shuffle(pool).slice(0,Math.min(pool.length,2+a.i));a.target=pick(a.stations);a.passengers=2+a.i+Math.floor(Math.random()*3);a.loaded=0;a.route=-1;a.note='Wpuść pasażerów do wagonu.';a.moving=false}
function expNeighbor(p,q){return Math.abs(p%6-q%6)+Math.abs(Math.floor(p/6)-Math.floor(q/6))===1}
function expLettersReady(){const a=expedition;if(a.found.length===a.word.length){a.stage='word';a.tiles=shuffle([...a.word].map((l,j)=>({l,j})));a.used=[];a.note='Wszystkie literki! Ułóż hasło do kufra.';say(a.word.toLowerCase(),true)}}
function expFinish(){const a=expedition;if(!a||a.done)return;a.done=true;const b=expProgress(a.id);b.unlocked=Math.max(b.unlocked,Math.min(2,a.i+1));if(!b.done.includes(a.i))b.done.push(a.i);const st=store.stats[a.id]||{done:0,help:0};st.done++;store.stats[a.id]=st;store.lastGame=a.id;if(['mine','submarine'].includes(a.id))collectWord(a.word);const prize=awardAlbum(a.id),decor=gift(false);save();otherScreen('expDone');app.innerHTML=top()+`<section class="panel finish exp-panel"><div class="pic reward-pop">${prize?.[0]||'🎁'} 🎉</div><h1>Wyprawa ukończona!</h1><p>${prize?'Twój skarb: '+esc(prize[1]):'Kolejny poziom odkryty!'}</p>${decor?`<p>${decor[0]} ${esc(decor[1])}</p>`:''}<div class="actions">${a.i<2?`<button class="primary" data-exp="start" data-id="${a.id}" data-i="${a.i+1}">Następny poziom ➜</button>`:''}<button class="small" data-exp="start" data-id="${a.id}" data-i="${a.i}">↻ Nowa runda</button><button class="small" data-exp="menu" data-id="${a.id}">🗺️ Poziomy</button><button class="small" data-active="album">🎁 Album</button><button class="small" data-act="home">🏠 Inne gry</button></div></section>`;say(pick(PRAISE));updateAtSafePoint();void checkForUpdates()}
function expRender(){const a=expedition,g=a.g;let body='';if(a.stage==='word'){body=`<div class="exp-center"><div class="pic">🧰 ${a.pic}</div><div class="big">${[...a.word].map((l,j)=>j<a.used.length?l:'_').join(' ')}</div><button class="primary" data-exp="say">🔊 Powiedz hasło</button><div class="letters">${a.tiles.map(t=>`<button class="letter" data-exp="letter" data-i="${t.j}" ${a.used.includes(t.j)?'disabled':''}>${t.l}</button>`).join('')}</div><button class="small" data-exp="help">💡 Podpowiedz literę</button></div>`}
 else if(a.id==='mine'||a.id==='submarine'){const mine=a.id==='mine';body=`<div class="exp-target"><span>${a.pic}</span><strong>${a.found.map(x=>x.letter).join(' ')||'· · ·'} (${a.found.length}/${a.word.length})</strong><button class="small" data-exp="say">🔊 Posłuchaj</button></div><div class="exp-grid ${mine?'mine-grid':'sea-grid'}">${range(0,23).map(p=>{const opened=mine&&a.open.includes(p),near=mine?a.open.some(q=>expNeighbor(q,p)):expNeighbor(a.pos,p),cell=a.cells[p],got=cell&&a.found.some(x=>x.index===cell.index),hard=mine&&a.hard.includes(p),rock=!mine&&a.rocks.includes(p);let ico=mine?opened?(got?'✨':'·'):hard?'🪨':'🟫':p===a.pos?'🟡🚤':got?'✨':rock?'🪸':cell?'💫':p%3===0?'🐠':'·';return `<button class="exp-cell ${opened?'dug':''} ${near?'near':''} ${!mine&&p===a.pos?'sub-here':''}" data-exp="cell" data-i="${p}" aria-label="${mine?'Skała':'Pole'} ${p+1}" ${mine&&opened?'disabled':''}>${ico}${mine&&a.hits[p]&&!opened?' <small>⛏️</small>':''}</button>`}).join('')}</div>${mine?'':'<div class="exp-dirs">'+[[-6,'⬆'],[-1,'⬅'],[1,'➡'],[6,'⬇']].map(([q,ico])=>`<button class="small" data-exp="move" data-i="${q}">${ico}</button>`).join('')+'</div>'}<button class="small" data-exp="guide">💡 Pokaż drogę</button>`}
 else if(a.id==='rail'){body=`<div class="exp-train-scene"><div class="exp-stations">${a.stations.map(([w,p],j)=>`<button class="exp-station ${a.route===j?'selected':''}" data-exp="route" data-i="${j}" ${a.moving?'disabled':''}><span>${p}</span><b>${w}</b></button>`).join('')}</div><div class="exp-track"><span class="exp-engine ${a.moving?'running':''}">🚂🚃</span></div></div><div class="exp-target"><span>🎫 ${a.target[1]}</span><strong>Bilet: ${a.target[0]}</strong><button class="small" data-exp="sayout">🔊 Posłuchaj</button></div><div class="exp-passengers">${range(0,a.passengers-1).map(j=>`<button class="small ${j<a.loaded?'aboard':''}" data-exp="board" ${j<a.loaded||a.moving?'disabled':''}>${j<a.loaded?'✅':'🐰'}</button>`).join('')}</div><p>W wagonie: ${a.loaded} / ${a.passengers}</p><button class="primary" data-exp="depart" ${a.moving?'disabled':''}>🚦 Ruszaj!</button><p class="sub">Podróż ${a.round+1} z ${a.goal}</p>`}
 else {body=`<div class="exp-target"><span>📜</span><strong>Przepis ${a.round+1}/${a.goal}</strong></div><div class="exp-recipe">${a.recipe.map((n,k)=>n?`<span>${EXP_COLORS[k][0]} × ${n}</span>`:'').join('')}</div><div class="exp-beaker"><svg viewBox="0 0 180 160" aria-hidden="true"><path d="M65 8h50v49l43 79q8 17-14 17H36q-22 0-14-17l43-79z" fill="#fff" stroke="#7e78a3" stroke-width="5"/><path d="M48 91h84l24 46q5 12-13 12H37q-18 0-13-12z" fill="${a.drops.every((n,k)=>n===a.recipe[k])?a.mix.color:a.drops.reduce((s,n)=>s+n,0)?'#b7a9db':'#e8eafa'}"/><circle cx="71" cy="122" r="5" fill="#fff9"/><circle cx="111" cy="136" r="7" fill="#fff9"/></svg><div>${a.drops.reduce((s,n)=>s+n,0)} kropli</div></div><div class="exp-ingredients">${EXP_COLORS.map(([ico,n],k)=>`<button class="small" data-exp="drop" data-i="${k}"><span>${ico}</span> + ${a.drops[k]}</button>`).join('')}</div><div class="actions"><button class="small" data-exp="undoDrop">↶ Cofnij</button><button class="small" data-exp="empty">🧽 Wylej</button><button class="primary" data-exp="mix">✨ Wymieszaj</button></div>`}
 app.innerHTML=top()+`<section class="panel exp-panel" style="--exp:${g.color}"><div class="exp-title"><h2>${g.icon} ${g.levels[a.i]}</h2><span>Poziom ${a.i+1}/3</span></div>${body}<p class="exp-note" role="status">${esc(a.note)}</p><div class="actions"><button class="small" data-exp="menu" data-id="${a.id}">🗺️ Poziomy</button>${a.id==='rail'||a.id==='potion'?'<button class="small" data-exp="hint">💡 Pomoc Luli</button>':''}</div></section>`}
function expClick(d){if(d.exp==='menu')return expMenu(d.id);if(d.exp==='start')return expStart(d.id,+d.i);if(screen!=='expPlay'||!expedition||expedition.done)return;const a=expedition,p=+d.i;if(a.moving)return;
 if(d.exp==='say'){say(a.word.toLowerCase(),true);return}if(d.exp==='sayout'){say(a.target[0].toLowerCase(),true);return}
 if(a.stage==='word'){if(d.exp==='letter'||d.exp==='help'){const t=d.exp==='help'?a.tiles.find(t=>!a.used.includes(t.j)&&t.l===a.word[a.used.length]):a.tiles.find(t=>t.j===p);if(!t||a.used.includes(t.j))return;if(t.l!==a.word[a.used.length])a.note='Posłuchaj jeszcze raz albo poproś o pomoc.';else{a.used.push(t.j);soundNote(620);if(a.used.length===a.word.length)return expFinish()}expRender()}return}
 if(a.id==='mine'&&(d.exp==='cell'||d.exp==='guide')){let q=p;if(d.exp==='guide'){q=range(0,23).find(n=>!a.open.includes(n)&&a.open.some(o=>expNeighbor(o,n)))}if(!Number.isInteger(q)||q<0||q>23||a.open.includes(q))return;if(!a.open.some(o=>expNeighbor(o,q))){a.note='Najpierw wykop tunel obok otwartej skały.';return expRender()}a.hits[q]=(a.hits[q]||0)+1;if(a.hard.includes(q)&&a.hits[q]<2){a.note='Twarda skała! Uderz jeszcze raz.';soundNote(180);return expRender()}a.open.push(q);soundNote(330);if(a.cells[q]){a.found.push(a.cells[q]);a.note='Znaleziono literę '+a.cells[q].letter+'!';soundNote(660);expLettersReady()}else a.note='Nowy tunel! Kop dalej.'}
 if(a.id==='submarine'&&['cell','move','guide'].includes(d.exp)){let q=d.exp==='move'?a.pos+p:p;if(d.exp==='guide'){const target=Object.keys(a.cells).map(Number).find(n=>!a.found.some(o=>o.index===a.cells[n].index));if(target===undefined)return;const x=a.pos%6,y=Math.floor(a.pos/6),tx=target%6,ty=Math.floor(target/6);q=x!==tx?a.pos+Math.sign(tx-x):a.pos+6*Math.sign(ty-y)}if(q<0||q>23||!expNeighbor(a.pos,q)){a.note='Płyń po jednym polu.';return expRender()}a.pos=q;const cell=a.cells[q];if(cell&&!a.found.some(o=>o.index===cell.index)){a.found.push(cell);a.note='Skarb: '+cell.letter;soundNote(680);expLettersReady()}else a.note=a.rocks.includes(q)?'Mijamy koralowiec.':'Płyń dalej!'}
 if(a.id==='rail'){if(d.exp==='board'&&a.loaded<a.passengers){a.loaded++;soundNote(440)}if(d.exp==='route'&&a.stations[p]){a.route=p;say(a.stations[p][0].toLowerCase(),true)}if(d.exp==='hint'){a.route=a.stations.indexOf(a.target);a.note='Zwrotnica ustawiona! Zaproś wszystkich pasażerów.'}if(d.exp==='depart'){if(a.loaded!==a.passengers)a.note='Zabierz jeszcze pasażerów.';else if(a.stations[a.route]!==a.target)a.note='Sprawdź obrazek na bilecie i stację.';else{a.moving=true;a.note='Pociąg rusza!';soundNote(392);expRender();const t=token;timer=setTimeout(()=>{if(screen!=='expPlay'||token!==t||expedition!==a)return;collectWord(a.target[0]);a.round++;if(a.round>=a.goal)return expFinish();expRailRound();expRender()},1100);return}}}
 if(a.id==='potion'){if(d.exp==='drop'&&p>=0&&p<3&&a.drops.reduce((s,n)=>s+n,0)<20){a.drops[p]++;a.stack=[...(a.stack||[]),p];soundNote(330+p*100)}if(d.exp==='undoDrop'&&a.stack?.length){a.drops[a.stack.pop()]--}if(d.exp==='empty'){a.drops=[0,0,0];a.stack=[]}if(d.exp==='hint'){a.note='Potrzebujesz: '+a.recipe.map((n,k)=>n?`${EXP_COLORS[k][0]} ${n}`:'').filter(Boolean).join(' + ')}if(d.exp==='mix'){if(a.drops.every((n,k)=>n===a.recipe[k])){a.note='Powstał '+a.mix.name.toLowerCase()+' eliksir!';a.moving=true;expRender();soundNote(523);soundNote(659,.15);soundNote(784,.3);say(a.mix.name,true);const t=token;timer=setTimeout(()=>{if(screen!=='expPlay'||token!==t||expedition!==a)return;a.moving=false;a.round++;if(a.round>=a.goal)return expFinish();a.stack=[];expPotionRound();expRender()},1600);return}else a.note='Porównaj liczbę kropli z przepisem. Możesz cofnąć.'}}
 expRender()}

